INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$a6de6dc5-9044-57c0-9c5c-b5020f96b085$ml$::uuid, $ml$ev$ml$, 1, 1, $ml${"id": "ev-d1-c1", "title": "A phone maker builds EVs", "lessonTitle": "Who makes the world's EVs", "slot": 1, "type": "apply", "brief": {"headline": "Xiaomi, best known for phones, handed over its first SU7 in April 2024. In 2025 it delivered over 410,000 EVs, and its batteries come from BYD and CATL.", "kicker": "Apply the map: what kind of carmaker is Xiaomi, and who powers it?", "fullText": "Xiaomi delivered its first SU7 sedan in April 2024 and added the YU7 SUV in summer 2025. Founder Lei Jun said it delivered over 410,000 EVs in 2025, and set a target of 550,000 for 2026.\n\nXiaomi designs and sells the cars, but it does not make the cells. The base SU7 first used BYD's Blade batteries from FinDreams, BYD's battery arm. To fix delivery delays, Xiaomi added CATL cells, and the Pro and Max versions use CATL packs. A brand new carmaker still runs through the same few battery makers.", "sources": [{"url": "https://www.electrive.com/2026/01/05/xiaomi-targets-over-550000-deliveries-this-year", "label": "electrive, Xiaomi targets over 550,000 deliveries"}, {"url": "https://cdn.cnevpost.com/2024/05/27/xiaomi-su7-standard-gets-random-catl-byd-batteries", "label": "CnEVPost, Xiaomi SU7 gets CATL and BYD batteries"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each company by what it builds.", "buckets": ["Carmaker", "Battery maker"], "items": [{"text": "Xiaomi, which sells the SU7 and YU7", "bucket": 0}, {"text": "Tesla, which sells the Model Y", "bucket": 0}, {"text": "Ford, a legacy carmaker adding EVs", "bucket": 0}, {"text": "CATL, maker of the SU7 Pro's Shenxing pack", "bucket": 1}, {"text": "FinDreams, BYD's battery arm", "bucket": 1}, {"text": "LG Energy Solution, a Korean cell maker", "bucket": 1}], "explanation": "Xiaomi, Tesla and Ford design and sell cars. CATL, FinDreams and LG Energy Solution make the cells those cars run on."}, "numbers": {"kind": "numberSense", "prompt": "About how many EVs did Xiaomi deliver in 2025, its first full year of sales?", "min": 0, "max": 1000, "value": 410, "unit": "K", "explanation": "Over 410,000, about a quarter of what Tesla delivered, from a company that sold its first car in April 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Xiaomi's EV unit. They ask what kind of carmaker Xiaomi is.", "prompt": "Which answer shows you know the map?", "options": ["A legacy carmaker moving to EVs", "A battery maker that also sells cars", "An EV-first newcomer that buys its cells"], "correctIndex": 2, "consequences": ["Xiaomi sold its first car in 2024; it has no gas car past.", "Xiaomi buys its cells from BYD and CATL; it does not make them.", "You place it right: new, EV only, and dependent on cell makers."], "explanation": "Xiaomi started with EVs in 2024 and sources cells from BYD and CATL. That makes it an EV-first carmaker, not a battery maker."}, "proReasoning": "Strong candidates name the type of company and its weak spot in one line: EV-first, and tied to outside cell makers for supply.", "commonMistake": "Treating every EV brand alike. A newcomer, a legacy carmaker and a battery maker face very different problems.", "mentalModel": "Name the company type, then its biggest dependency."}, "invest": {"call": {"kind": "theCall", "situation": "Xiaomi targets 550,000 deliveries in 2026, up 34%. You are judging how realistic that is.", "prompt": "What should you check first?", "options": ["Whether its cell suppliers can grow with it", "How many phones Xiaomi sold last year", "Whether Tesla also raised its targets"], "correctIndex": 0, "consequences": ["In 2024, cell supply was what slowed SU7 deliveries.", "Phone sales do not put batteries into cars.", "A rival's target says little about Xiaomi's output."], "explanation": "Xiaomi added CATL cells in 2024 to fix delivery delays. Growth targets only hold if the battery makers can supply more cells."}, "proReasoning": "Investors test a carmaker's growth plan against its battery supply. More cars need more cells, and cells come from a few firms.", "commonMistake": "Taking a sales target at face value without asking what could cap production.", "mentalModel": "Check the cells behind every delivery target."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes software that compares battery cells from different suppliers. You want a first customer.", "prompt": "Which company has that exact problem?", "options": ["A lithium mine selling raw ore", "A carmaker using cells from two makers", "A phone shop selling Xiaomi phones"], "correctIndex": 1, "consequences": ["A mine sells ore and never sees finished cells.", "Xiaomi runs BYD and CATL cells side by side in one model.", "A phone shop never chooses between EV cell suppliers."], "explanation": "A carmaker mixing suppliers, like Xiaomi with BYD and CATL in the SU7, has to compare cells every day."}, "proReasoning": "Founders look for a customer who already lives with the problem. Two cell suppliers in one model means constant comparison work.", "commonMistake": "Pitching a tool to a company that never faces the choice it helps with.", "mentalModel": "Sell to whoever makes the choice your tool improves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says Xiaomi makes its own car batteries, like it makes its own phones.", "prompt": "What's the more accurate picture?", "options": ["It builds every cell in its own plant", "Its cars run on phone batteries", "It buys cells from BYD and CATL"], "correctIndex": 2, "consequences": ["Xiaomi added a second supplier because it does not make cells.", "Car packs are far larger and built by cell makers.", "The SU7 uses BYD Blade cells and CATL packs."], "explanation": "Xiaomi designs and sells the car. Its cells come from BYD and CATL, two of the biggest battery makers."}, "proReasoning": "Ask who designs the car and who makes the cells inside. They are often different companies.", "commonMistake": "Assuming the brand on the car makes everything inside it.", "mentalModel": "The brand designs the car; cell makers power it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e5029883b0cc$ml$]::text[]),
($ml$cc7ca10b-1c81-5d9a-9c14-6c8b0b1ef29b$ml$::uuid, $ml$ev$ml$, 1, 2, $ml${"id": "ev-d1-c2", "title": "Counting cars two ways", "lessonTitle": "Who makes the world's EVs", "slot": 2, "type": "connect", "brief": {"headline": "BYD sold 2.26 million battery-electric cars in 2025 and about 2.29 million plug-in hybrids. Tesla delivered 1.64 million cars, all battery-electric.", "kicker": "Connect two ideas: car types and who leads depend on what you count.", "fullText": "Day 1 split EVs into two types. A battery-electric car, or BEV, runs only on its battery. A plug-in hybrid adds a gas engine as a backup.\n\nThat split decides who looks biggest. Count only BEVs and BYD still leads, with 2,256,714 against Tesla's 1,636,129. Count plug-in hybrids too and BYD sold more than twice as many cars, because it sells about as many hybrids as pure EVs. Tesla sells only battery-electric cars.", "sources": [{"url": "https://www.electrive.com/2026/01/02/byd-overtakes-tesla-as-worlds-largest-", "label": "electrive, BYD overtakes Tesla"}, {"url": "https://ir.tesla.com/press-release/tesla-fourth-quarter-2025-production-deliveries-deployments", "label": "Tesla Q4 2025 deliveries"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["BYD sold more battery-electric cars than Tesla in 2025.", "Tesla sold about 2 million plug-in hybrids in 2025.", "BYD sold about as many plug-in hybrids as pure EVs."], "fakeIndex": 1, "explanation": "Tesla sells no plug-in hybrids. All 1.64 million of its 2025 deliveries were battery-electric."}, "numbers": {"kind": "numberSense", "prompt": "BEVs plus plug-in hybrids: about how many plug-in cars did BYD sell in 2025?", "min": 0, "max": 6, "value": 4.5, "unit": "M", "explanation": "About 2.26 million BEVs plus about 2.29 million plug-in hybrids, roughly 4.5 million in all."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're preparing a market slide for a job interview at a carmaker. You want to compare BYD and Tesla fairly.", "prompt": "How do you show it?", "options": ["Split BEVs and plug-in hybrids", "Add every plug-in car into one total", "Show only total company revenue"], "correctIndex": 0, "consequences": ["BYD leads in both, and the slide shows how much each type adds.", "One total hides that Tesla sells no hybrids at all.", "Revenue mixes cars with batteries and other businesses."], "explanation": "A fair comparison splits the two car types. BYD's lead looks very different with and without plug-in hybrids."}, "proReasoning": "Good analysts state what they count before comparing. BEV-only and BEV-plus-hybrid totals tell different stories.", "commonMistake": "Quoting one headline number without saying which car types are inside it.", "mentalModel": "Say what you count, then compare."}, "invest": {"call": {"kind": "theCall", "situation": "A report says BYD sold more than twice as many EVs as Tesla in 2025. You hold both stocks.", "prompt": "What should you check before acting?", "options": ["How many stores each company has", "How many of those were hybrids", "Whether BYD's cars cost more"], "correctIndex": 1, "consequences": ["Store counts say little about the type of cars sold.", "About half of BYD's plug-in sales were hybrids with gas engines.", "Price matters, but it does not explain the count gap."], "explanation": "The two-times figure includes plug-in hybrids. In battery-electric cars alone, BYD led by about 620,000."}, "proReasoning": "Investors read the definition behind a market share claim. Hybrids and pure EVs earn and compete differently.", "commonMistake": "Trading on a share headline without knowing which cars it counts.", "mentalModel": "Check the definition behind every share claim."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells home chargers. You want to estimate demand from new plug-in car sales.", "prompt": "Which buyers count as your market?", "options": ["Only owners of a Tesla Model Y", "Only buyers of new gas cars", "Both BEV and plug-in hybrid owners"], "correctIndex": 2, "consequences": ["Tesla is one brand of many that plug in.", "Gas cars never plug in, so they need no charger.", "Both types plug in at home, so both can buy a charger."], "explanation": "Plug-in hybrids charge from the wall too. Leaving them out would shrink your market by about half for a brand like BYD."}, "proReasoning": "Founders size a market by who has the need, not by brand. Anything with a plug can use a charger.", "commonMistake": "Sizing the market with the wrong definition of an EV.", "mentalModel": "Count everyone who has the need."}, "curiosity": {"call": {"kind": "theCall", "situation": "A headline says BYD dwarfs Tesla. Your friend asks if Tesla's sales collapsed.", "prompt": "What's the more accurate picture?", "options": ["BYD leads, partly by counting hybrids", "Tesla stopped making cars in 2025", "BYD sells only pure electric cars"], "correctIndex": 0, "consequences": ["Both sold over 1.6 million BEVs; hybrids add BYD's extra lead.", "Tesla delivered 1.64 million cars in 2025.", "BYD sold about 2.29 million plug-in hybrids too."], "explanation": "BYD leads even in pure EVs, but its hybrids make the gap look much bigger."}, "proReasoning": "Ask what is being counted. \"EV\" can mean battery-only cars or include plug-in hybrids.", "commonMistake": "Reading a bigger number as a collapse of the smaller rival.", "mentalModel": "Ask what counts as an EV in the headline."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:68d2d1f2061d$ml$]::text[]),
($ml$54d32a70-c07d-577e-96f5-9902764e6a93$ml$::uuid, $ml$ev$ml$, 1, 3, $ml${"id": "ev-d1-c3", "title": "One supplier or two?", "lessonTitle": "Who makes the world's EVs", "slot": 3, "type": "decide", "brief": {"headline": "CATL installed 39.2% of the world's EV batteries in 2025, and BYD 16.4%. You are launching your first EV line and must pick where the cells come from.", "kicker": "Decide: how do you source cells for a new EV line?", "fullText": "You run the EV program at a carmaker launching its first battery-electric model. Every EV maker depends on the same few cell makers. CATL alone installed 39.2% of all EV batteries in 2025, and BYD came second with 16.4%.\n\nOne supplier is simpler and can win a better price. Two suppliers cost more effort but protect your launch if one falls short, which is why Xiaomi added CATL next to BYD when SU7 deliveries lagged.", "sources": [{"url": "https://cnevpost.com/2026/02/04/global-ev-battery-market-share-2025/", "label": "CnEVPost on SNE Research 2025 battery shares"}, {"url": "https://cdn.cnevpost.com/2024/05/27/xiaomi-su7-standard-gets-random-catl-byd-batteries", "label": "CnEVPost, Xiaomi SU7 gets CATL and BYD batteries"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan protects a first EV launch better?", "left": {"name": "One cell supplier", "note": "Simpler, but one point of failure"}, "right": {"name": "Two cell suppliers", "note": "More work, but a backup if one slips"}, "correctIndex": 1, "explanation": "A second supplier keeps the line moving if the first one falls short. Xiaomi added CATL for exactly that reason."}, "numbers": {"kind": "numberSense", "prompt": "What share of the world's EV batteries did CATL install in 2025?", "min": 0, "max": 100, "value": 39, "unit": "%", "explanation": "39.2%, more than twice BYD's 16.4%. Few carmakers can avoid CATL entirely."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how you'd source cells for a carmaker's first EV.", "prompt": "Which answer shows you see the risk?", "options": ["Wait until cell prices stop falling", "Qualify a second supplier as a backup", "Pick the cheapest single supplier"], "correctIndex": 1, "consequences": ["Waiting delays the launch while rivals sell cars.", "You show you know one slip can stall a whole launch.", "Cheapest alone ignores what happens if supply fails."], "explanation": "With a few firms making most cells, a backup supplier protects the launch. It shows you think about supply, not only price."}, "proReasoning": "A strong answer weighs price against continuity: one supplier for scale, a second to avoid a single point of failure.", "commonMistake": "Choosing on price alone, as if every supplier always delivers on time.", "mentalModel": "Balance price against the cost of a stalled line."}, "invest": {"call": {"kind": "theCall", "situation": "Two young EV makers look alike. One buys all its cells from CATL; the other splits them between CATL and BYD.", "prompt": "Which carries less supply risk?", "options": ["The one that relies on CATL alone", "Both carry exactly the same risk", "The one with two suppliers"], "correctIndex": 2, "consequences": ["A single supplier is a single point of failure.", "A backup source changes what one disruption can do.", "If one supplier slips, the other keeps cars moving."], "explanation": "Two suppliers spread the risk. A problem at one cell maker does not stop every car."}, "proReasoning": "Investors read supplier lists. A single source for the most expensive part is a risk worth pricing in.", "commonMistake": "Ignoring where the cells come from when comparing EV makers.", "mentalModel": "Price in single-supplier risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a small electric delivery van. Only CATL has quoted you so far.", "prompt": "What do you do before signing?", "options": ["Seek a second quote from another maker", "Sign the CATL deal for all volume", "Design the van to need no battery"], "correctIndex": 0, "consequences": ["A second quote tests the price and gives you a fallback.", "You lock in one source with no backup.", "An electric van needs a battery to move."], "explanation": "Even a small maker benefits from a second quote. It improves the price and gives you a plan B."}, "proReasoning": "Founders treat their most expensive input like a key hire: have a backup before you depend on it.", "commonMistake": "Signing the first quote because it is the biggest name.", "mentalModel": "Never depend on one quote for your most costly part."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why so many different EV brands mention the same battery makers.", "prompt": "What's the reason?", "options": ["Battery makers are owned by every carmaker", "A few firms make most of the cells", "Each brand makes its own cells"], "correctIndex": 1, "consequences": ["They are separate companies selling to many carmakers.", "CATL and BYD alone installed over half of EV batteries in 2025.", "Most carmakers buy cells rather than make them."], "explanation": "CATL installed 39.2% and BYD 16.4% of 2025 EV batteries. Most brands buy from the same few makers."}, "proReasoning": "Follow the battery. It links brands that look like rivals to the same suppliers.", "commonMistake": "Assuming rival car brands share nothing.", "mentalModel": "Rival brands often share a battery maker."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ec7eec52c29f$ml$]::text[]),
($ml$622c124d-e286-5345-b347-dde783f77ad9$ml$::uuid, $ml$ev$ml$, 2, 1, $ml${"id": "ev-d2-c1", "title": "GM's $1.6 billion write-down", "lessonTitle": "Where the money in an EV goes", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, GM took a $1.6 billion charge on its EV plans. About $1.2 billion was idle EV equipment; $400 million was canceled supplier contracts.", "kicker": "Apply it: where did the money in these EVs go?", "fullText": "On October 14, 2025, GM told regulators it would take about $1.6 billion in charges. About $1.2 billion covered EV machinery and equipment it no longer expected to use. About $400 million came mostly from canceling supplier contracts for parts and materials.\n\nGM had invested to meet emission rules it expected to tighten. Then the $7,500 tax credit ended and the rules eased, and GM expected EV demand to slow. Money spent on capacity for cars that never sell still has to be paid for.", "sources": [{"url": "https://www.cpapracticeadvisor.com/2025/10/15/gm-reports-1-6b-hit-from-now-unused-ev-investments/170945/", "label": "CPA Practice Advisor, GM reports $1.6B EV hit"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the steps behind the charge in order.", "steps": ["GM invests in EV machines and supplier deals", "Emission rules ease and the tax credit ends", "GM expects fewer EV sales than planned", "Machines sit idle and contracts are canceled", "GM books a $1.6 billion charge"], "explanation": "Spending came first, based on expected rules and demand. When both changed, the unused capacity became a loss."}, "numbers": {"kind": "numberSense", "prompt": "Of the $1.6 billion, about how much was for idle EV equipment, in billions?", "min": 0, "max": 2, "value": 1.2, "unit": "B", "explanation": "About $1.2 billion. The other $400 million was mostly canceled supplier contracts."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for GM's EV planning team after the $1.6 billion charge.", "prompt": "What do you say the team must get better at?", "options": ["Matching capacity to real demand", "Buying more machines up front", "Ignoring policy when planning"], "correctIndex": 0, "consequences": ["Idle machines were the bulk of the charge.", "Buying ahead of demand is what created the loss.", "Policy shifts are what cut demand here."], "explanation": "Most of the charge came from equipment sized for demand that did not come. Pacing spending to demand is the fix."}, "proReasoning": "Strong candidates link the loss to its cause: capacity built for a demand forecast that changed with policy.", "commonMistake": "Treating a write-down as bad luck instead of a planning lesson.", "mentalModel": "Build capacity at the pace demand proves itself."}, "invest": {"call": {"kind": "theCall", "situation": "GM books a $1.6 billion EV charge. You are reading its results.", "prompt": "What does the charge mostly tell you?", "options": ["GM has no gas car business left", "Past EV spending will not earn back", "GM sold no EVs that quarter"], "correctIndex": 1, "consequences": ["GM still builds and sells many gas vehicles.", "An impairment means an asset will not earn what was planned.", "GM more than doubled EV sales in that same quarter."], "explanation": "An impairment writes down assets that will not pay off as planned. It looks back at spending, not at that quarter's sales."}, "proReasoning": "Investors separate one-time charges from ongoing results, then ask whether more charges could follow.", "commonMistake": "Reading a write-down as a sales collapse.", "mentalModel": "A charge looks back at spending that will not pay off."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes parts for EV lines. GM just canceled supplier contracts worth about $400 million.", "prompt": "What should you change?", "options": ["Hire ahead for the next GM order", "Sign longer deals with one carmaker", "Win customers beyond one EV program"], "correctIndex": 2, "consequences": ["Hiring for orders that may vanish adds risk.", "One customer can cancel, as GM just did.", "Spreading customers protects you when one program shrinks."], "explanation": "Suppliers took part of the hit through canceled contracts. A wider customer base cushions you when one carmaker pulls back."}, "proReasoning": "Founders who sell into EVs avoid betting on one program. When plans change, suppliers feel it first.", "commonMistake": "Building your whole business around one carmaker's forecast.", "mentalModel": "Spread your customers across programs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says GM lost $1.6 billion because nobody wanted its EVs.", "prompt": "What's the more accurate picture?", "options": ["It wrote off capacity built for more EVs", "It sold zero EVs in all of 2025", "It gave $1.6 billion back to buyers"], "correctIndex": 0, "consequences": ["Idle machines and canceled contracts made up the charge.", "GM more than doubled EV sales in the third quarter.", "The charge covered equipment and contracts, not buyers."], "explanation": "GM still sold EVs. The charge was for machines and contracts sized for more demand than it now expects."}, "proReasoning": "Ask what a loss is made of. Here it was unused equipment and canceled deals, not missing customers.", "commonMistake": "Assuming a big loss means sales stopped.", "mentalModel": "Look inside a loss before judging it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0b47ecd3eece$ml$]::text[]),
($ml$58775658-cf6d-5c23-abbe-56c0508cec98$ml$::uuid, $ml$ev$ml$, 2, 2, $ml${"id": "ev-d2-c2", "title": "Who makes the money", "lessonTitle": "Where the money in an EV goes", "slot": 2, "type": "connect", "brief": {"headline": "Ford's EV unit lost $4.8 billion in 2025. CATL, the cell maker behind many EVs, installed 39.2% of the world's EV batteries that year.", "kicker": "Connect day 1 and day 2: the battery layer and the losses.", "fullText": "On day 1 you followed the battery: a few cell makers supply almost every EV maker, and CATL alone installed 39.2% of EV batteries in 2025. On day 2 you saw where the money goes, with the battery pack as a major cost.\n\nPut them together. Ford's Model e unit lost $4.8 billion in 2025, while its gas and commercial units earned $3.0 billion and $6.8 billion. A carmaker pays the battery maker for every pack it buys, whether or not its own EVs earn a profit.", "sources": [{"url": "https://cnevpost.com/2026/02/04/global-ev-battery-market-share-2025/", "label": "CnEVPost on SNE Research 2025 battery shares"}, {"url": "https://s205.q4cdn.com/882619693/files/doc_financials/2025/q4/Ford-Q4-2025-Earnings-Press-Release.pdf", "label": "Ford Q4 2025 earnings"}, {"url": "https://about.bnef.com/insights/clean-transport/lithium-ion-battery-pack-prices-fall-to-108-per-kilowatt-hour-despite-rising-metal-prices-bloombergnef/", "label": "BloombergNEF battery price survey 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Who gets paid for every EV Ford builds, even when Model e loses money?", "left": {"name": "Ford Model e", "note": "Lost $4.8 billion in 2025"}, "right": {"name": "Its battery supplier", "note": "Paid for every pack Ford buys"}, "correctIndex": 1, "explanation": "The cell maker is paid per pack. The carmaker only profits if the whole car sells for more than it costs."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did Ford's EV unit lose in 2025?", "min": 0, "max": 12, "value": 4.8, "unit": "B", "explanation": "$4.8 billion. Ford Pro earned $6.8 billion and Ford Blue $3.0 billion that year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a battery maker that supplies several carmakers. They ask why they can earn while clients lose money.", "prompt": "Which answer shows you get the economics?", "options": ["Carmakers share their EV losses with us", "We are paid per pack, whatever the car earns", "Our clients pay us out of their profits"], "correctIndex": 1, "consequences": ["Losses stay with the carmaker unless a contract says otherwise.", "You show you know how the supplier gets paid.", "Model e had no profit to pay from in 2025."], "explanation": "A cell maker sells packs at a price. The carmaker carries the risk of whether the finished car earns money."}, "proReasoning": "Strong candidates explain who carries which risk. Suppliers carry price risk; carmakers carry the risk the car does not pay off.", "commonMistake": "Assuming suppliers and carmakers rise and fall on the same profit.", "mentalModel": "Name who gets paid, and when."}, "invest": {"call": {"kind": "theCall", "situation": "You want exposure to EV growth but worry carmakers still lose money on EVs.", "prompt": "Which layer avoids that specific risk?", "options": ["A legacy carmaker's EV unit", "An EV startup with no profits", "A large battery cell maker"], "correctIndex": 2, "consequences": ["Ford's EV unit lost $4.8 billion in 2025.", "Startups add their own cash burn risk.", "It is paid per pack across many carmakers."], "explanation": "A cell maker sells to many carmakers and is paid per pack, so it does not carry one carmaker's EV losses directly."}, "proReasoning": "Investors pick the layer that matches their thesis. EV volume growth can pay a supplier even when carmakers struggle.", "commonMistake": "Assuming owning a carmaker is the only way to bet on EV growth.", "mentalModel": "Pick the layer that earns from your thesis."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup can cut pack cost by 5%. You must decide who to sell to first.", "prompt": "Who feels that saving most directly?", "options": ["A carmaker losing money on its EVs", "A carmaker with no EVs planned", "A drivers' club for gas cars"], "correctIndex": 0, "consequences": ["Every dollar off the pack helps close its losses.", "It buys no packs, so it saves nothing.", "Gas car owners never buy a pack."], "explanation": "The battery is the costliest part. A carmaker losing billions on EVs gains most from a cheaper pack."}, "proReasoning": "Founders pitch savings to whoever is bleeding. A loss-making EV unit is hunting for every dollar off the pack.", "commonMistake": "Pitching a cost cut to someone without the cost.", "mentalModel": "Sell savings to whoever carries the cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn Ford lost billions on EVs but battery makers grew. You wonder how both can be true.", "prompt": "What's the explanation?", "options": ["Ford stopped buying batteries in 2025", "Battery makers are paid for every pack", "Battery makers sell cars at a loss too"], "correctIndex": 1, "consequences": ["Ford kept building EVs and buying packs.", "They earn on each pack, while the car itself may lose money.", "Battery makers sell cells, not finished cars."], "explanation": "The supplier is paid when it delivers a pack. Whether the car later earns money is the carmaker's problem."}, "proReasoning": "In any chain, ask who is paid first. They can earn while the brand at the end loses.", "commonMistake": "Thinking every company in a chain wins or loses together.", "mentalModel": "Suppliers can win while brands lose."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e557b1cdc6d7$ml$]::text[]),
($ml$4620f8d1-7715-573c-bc52-c1cf0d65b2b4$ml$::uuid, $ml$ev$ml$, 2, 3, $ml${"id": "ev-d2-c3", "title": "Pricing your EV", "lessonTitle": "Where the money in an EV goes", "slot": 3, "type": "decide", "brief": {"headline": "EV packs averaged $99 per kWh in 2025. In China they averaged $84; North America paid 44% more and Europe 56% more.", "kicker": "Decide: where should you build the pack for a new EV?", "fullText": "You run product planning for a carmaker designing a 75 kWh EV. At the 2025 average of $99 per kWh, the pack alone costs about $7,425.\n\nWhere you build matters. Packs in China averaged $84 per kWh. North America paid 44% more and Europe 56% more. Battery cost decides who can make money, so the cheapest region can decide whether a model earns money.", "sources": [{"url": "https://about.bnef.com/insights/clean-transport/lithium-ion-battery-pack-prices-fall-to-108-per-kilowatt-hour-despite-rising-metal-prices-bloombergnef/", "label": "BloombergNEF battery price survey 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which region had the cheapest EV battery packs in 2025?", "options": ["North America", "China", "Europe"], "correctIndex": 1, "explanation": "Packs in China averaged $84 per kWh. Europe paid 56% more and North America 44% more."}, "numbers": {"kind": "numberSense", "prompt": "At $84 per kWh, about how much does a 75 kWh pack cost in China, in thousands of dollars?", "min": 0, "max": 15, "value": 6.3, "unit": "K", "explanation": "75 times $84 is $6,300, about $1,100 less than the $7,425 global average."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a product strategy interview, you're asked why the same EV costs more to build in Europe.", "prompt": "Which answer goes to the main cause?", "options": ["European drivers want bigger seats", "Paint is more costly in Europe", "Packs cost 56% more there than in China"], "correctIndex": 2, "consequences": ["Seat size barely moves the cost of an EV.", "Paint is a tiny share next to the battery.", "The battery is the biggest cost, and its price varies by region."], "explanation": "The pack is the largest single cost, and Europe paid 56% more per kWh than China in 2025."}, "proReasoning": "Strong candidates start with the largest cost line. In EVs, that is almost always the battery.", "commonMistake": "Explaining cost gaps with small items while ignoring the pack.", "mentalModel": "Start with the biggest cost line."}, "invest": {"call": {"kind": "theCall", "situation": "Two carmakers sell similar EVs at similar prices. One buys packs in China, the other in Europe.", "prompt": "Which likely earns more per car?", "options": ["The one buying packs in China", "The one buying packs in Europe", "Both earn the same per car"], "correctIndex": 0, "consequences": ["Cheaper packs leave more profit at the same price.", "Its packs cost about 56% more than China's.", "A gap this large in the costliest part changes margins."], "explanation": "At the same selling price, the cheaper pack leaves more profit per car."}, "proReasoning": "Investors trace margins back to where the battery is made. It can matter more than the brand.", "commonMistake": "Comparing EV makers on price alone, ignoring pack cost.", "mentalModel": "Same price, cheaper pack, more profit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans a cheap electric scooter for Europe. Pack cost will decide your price.", "prompt": "What is your first sourcing move?", "options": ["Use the costliest supplier for quality", "Get quotes for packs made in China", "Build your own cell plant in Europe"], "correctIndex": 1, "consequences": ["Paying the most hurts the cheap price you aim for.", "China had the lowest pack prices in 2025.", "A new cell plant costs far more than a startup has."], "explanation": "China packs averaged $84 per kWh in 2025, the cheapest region. For a price-led product, that is the first quote to get."}, "proReasoning": "Founders aiming at a low price start where the key part is cheapest, then check tariffs and shipping.", "commonMistake": "Committing to a costly supply chain before testing the cheapest option.", "mentalModel": "Quote the cheapest region first, then add the extras."}, "curiosity": {"call": {"kind": "theCall", "situation": "You notice EVs tend to cost less in China than similar models elsewhere.", "prompt": "Which fact helps explain it?", "options": ["Chinese EVs have no batteries", "Steel is free in China", "Battery packs are cheapest there"], "correctIndex": 2, "consequences": ["Every EV needs a battery.", "Steel costs money everywhere.", "Packs averaged $84 per kWh in China in 2025."], "explanation": "The battery is the costliest part, and China had the lowest pack prices in 2025."}, "proReasoning": "When prices differ, look at the most expensive part first. In EVs it is the battery.", "commonMistake": "Guessing at small causes for a big price gap.", "mentalModel": "Look at the biggest part first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:79b87c362f85$ml$]::text[]),
($ml$2aee705f-9063-538f-81f4-08b07b327dc0$ml$::uuid, $ml$ev$ml$, 3, 1, $ml${"id": "ev-d3-c1", "title": "Ford's licensed battery plant", "lessonTitle": "Who controls the EV supply chain", "slot": 1, "type": "apply", "brief": {"headline": "Ford is building a Michigan plant to make LFP cells using technology licensed from CATL. In 2023 it cut the plan from 35 GWh a year to about 20 GWh.", "kicker": "Apply it: who holds the power when the know-how is licensed?", "fullText": "In February 2023, Ford announced a $3.5 billion plant in Marshall, Michigan, to make LFP cells. The technology is licensed from CATL, the world's biggest cell maker. Until the plant opens, Ford buys LFP cells from CATL directly.\n\nIn November 2023, Ford scaled the plan back from about 35 GWh a year and 2,500 jobs to about 20 GWh and more than 1,700 jobs, with production still set for 2026. Federal officials criticized the CATL link. Ford owns the plant, but the recipe comes from China.", "sources": [{"url": "https://www.ameslab.gov/news/ford-opening-michigan-plant-to-make-batteries-that-could-bring-ev-costs-down", "label": "Ames Lab on Ford's Michigan LFP plant"}, {"url": "https://americanmachinist.com/news/article/21277815/ford-scales-back-michigan-ev-battery-plant", "label": "American Machinist, Ford scales back Michigan battery plant"}]}, "evidence": {"kind": "sortSignal", "prompt": "What does each side bring to the Marshall plant?", "buckets": ["Ford brings", "CATL brings"], "items": [{"text": "The factory building in Michigan", "bucket": 0}, {"text": "The workers and the investment", "bucket": 0}, {"text": "The LFP cell technology", "bucket": 1}, {"text": "LFP cells sold to Ford before the plant opens", "bucket": 1}], "explanation": "Ford owns and staffs the plant. CATL licenses the know-how and supplies cells until production starts."}, "numbers": {"kind": "numberSense", "prompt": "After the cut, about how many GWh a year is the Marshall plant planned to make?", "min": 0, "max": 50, "value": 20, "unit": "GWh", "explanation": "About 20 GWh, down from about 35 GWh in the original plan."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for Ford's battery team. They ask what the CATL license means for Ford.", "prompt": "Which answer shows you see the power balance?", "options": ["CATL owns and runs the Michigan plant", "Ford owns the plant; CATL owns the recipe", "Ford now controls CATL's technology"], "correctIndex": 1, "consequences": ["Ford owns the plant and licenses the know-how.", "You name both what Ford gains and what it still depends on.", "A license grants use, not control of the technology."], "explanation": "Ford builds and runs the plant, but the cell technology is licensed from CATL. Power stays with whoever owns the know-how."}, "proReasoning": "Strong candidates separate owning a plant from owning the technology inside it. The second is where power sits.", "commonMistake": "Assuming a US plant means US control of the technology.", "mentalModel": "Ask who owns the plant and who owns the recipe."}, "invest": {"call": {"kind": "theCall", "situation": "Ford relies on CATL technology for its Michigan LFP plant, and lawmakers criticize the link.", "prompt": "What risk should you watch?", "options": ["CATL buying all of Ford outright", "LFP cells ceasing to work in the US cold", "Rules that could hit subsidies for the plant"], "correctIndex": 2, "consequences": ["Nothing suggests a takeover; it is a license.", "The chemistry works the same everywhere.", "Some lawmakers argued the link should block federal support."], "explanation": "The CATL license drew political criticism and calls to deny subsidies. Policy risk follows the technology's origin."}, "proReasoning": "Investors look past the plant to whose technology it uses, because politics can follow the license.", "commonMistake": "Ignoring where the know-how comes from when valuing a battery plant.", "mentalModel": "The origin of the technology can carry policy risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has an LFP cell design. A big carmaker wants to license it instead of buying cells.", "prompt": "What should you protect in the deal?", "options": ["Ownership of the technology", "The right to run their factory", "A promise to never sell cells"], "correctIndex": 0, "consequences": ["Keeping the know-how keeps your power, as CATL does.", "Running their plant is costly and not where value sits.", "Giving up cell sales throws away a revenue line."], "explanation": "CATL licenses its LFP know-how to Ford but keeps ownership. That keeps CATL needed and paid."}, "proReasoning": "Founders who license technology keep the rights. The license earns money; ownership keeps you essential.", "commonMistake": "Selling the technology outright for a quick payment.", "mentalModel": "License the recipe; keep the rights."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that Ford will make batteries in Michigan. A friend says that ends its reliance on China.", "prompt": "What's the more accurate picture?", "options": ["The plant makes gas engines, not cells", "The cell technology is licensed from CATL", "Ford invented a new battery in Michigan"], "correctIndex": 1, "consequences": ["It is planned to make LFP battery cells.", "The plant runs on Chinese know-how, even if built in the US.", "The LFP design comes from CATL."], "explanation": "Ford builds the plant, but the LFP technology is licensed from China's CATL."}, "proReasoning": "Ask where the know-how comes from, not just where the factory stands.", "commonMistake": "Thinking a local factory means local technology.", "mentalModel": "A local plant can run on foreign know-how."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:74cb4b456f59$ml$]::text[]),
($ml$4877ba3f-65e2-528b-b3ce-0c3cea5ccd34$ml$::uuid, $ml$ev$ml$, 3, 2, $ml${"id": "ev-d3-c2", "title": "Where the cheap packs come from", "lessonTitle": "Who controls the EV supply chain", "slot": 2, "type": "connect", "brief": {"headline": "China made over 80% of the world's battery cells in 2025, and its EV packs averaged $84 per kWh. North America paid 44% more.", "kicker": "Connect day 2 and day 3: cheap packs and who makes the cells.", "fullText": "On day 2 you saw that pack cost decides who can make money, and packs in China averaged $84 per kWh in 2025, against 44% more in North America and 56% more in Europe. On day 3 you saw that China made over 80% of battery cells that year.\n\nThe two facts are linked. The country that makes most of the cells also has the cheapest packs. Carmakers elsewhere face a choice between cheaper Chinese supply and paying more for cells made closer to home.", "sources": [{"url": "https://about.bnef.com/insights/clean-transport/lithium-ion-battery-pack-prices-fall-to-108-per-kilowatt-hour-despite-rising-metal-prices-bloombergnef/", "label": "BloombergNEF battery price survey 2025"}, {"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["China made over 80% of battery cells in 2025.", "Packs in China were the cheapest of any region.", "Packs in Europe cost less than in China."], "fakeIndex": 2, "explanation": "Europe paid about 56% more per kWh than China in 2025."}, "numbers": {"kind": "numberSense", "prompt": "China packs averaged $84 per kWh. At 44% more, about what did North America pay per kWh?", "min": 0, "max": 200, "value": 121, "unit": "$", "explanation": "$84 times 1.44 is about $121 per kWh, roughly $37 more for every kWh."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A carmaker interviewer asks why its US-built EV costs more than a Chinese rival's.", "prompt": "Which answer links the cost to the supply chain?", "options": ["US workers build each car more slowly", "Chinese cars use smaller, cheaper wheels", "China makes most cells and has cheaper packs"], "correctIndex": 2, "consequences": ["Labor matters less than the cost of the pack.", "Wheel size barely moves an EV's cost.", "You tie the cost gap to where cells are made."], "explanation": "China made over 80% of cells and had the cheapest packs. That gap flows straight into the cost of the car."}, "proReasoning": "Strong answers connect a cost gap to the supply chain behind it, not just to the factory floor.", "commonMistake": "Blaming the assembly line while ignoring the battery.", "mentalModel": "Trace cost gaps back to where cells are made."}, "invest": {"call": {"kind": "theCall", "situation": "A US carmaker plans to switch to US-made cells to reduce China reliance.", "prompt": "What should you expect for its costs?", "options": ["Higher pack costs, at least at first", "Packs that get cheaper overnight", "No change to its battery costs"], "correctIndex": 0, "consequences": ["North American packs cost 44% more than China's in 2025.", "Nothing suggests local cells are instantly cheaper.", "Moving supply changes the price of the costliest part."], "explanation": "Packs outside China cost more in 2025. Less reliance usually means higher costs unless subsidies close the gap."}, "proReasoning": "Investors price the trade-off: less dependence on China often costs more per kWh.", "commonMistake": "Assuming supply chain safety comes free.", "mentalModel": "Safer supply usually costs more."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes cells in Canada. Carmakers say your price is higher than Chinese cells.", "prompt": "What do you sell besides price?", "options": ["Cells that need no testing", "Supply outside China's control", "A promise to undercut CATL on price"], "correctIndex": 1, "consequences": ["Every cell must be tested before use.", "With over 80% of cells from China, a second source has value.", "Beating China's pack prices is very hard."], "explanation": "With China making over 80% of cells, carmakers value a source outside it. That is the pitch when you can't win on price."}, "proReasoning": "Founders who cannot win on price sell what the market lacks: supply that does not run through one country.", "commonMistake": "Trying to beat the cheapest maker on price alone.", "mentalModel": "Sell what concentration leaves missing."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why batteries are so much cheaper in China than elsewhere.", "prompt": "Which fact best explains it?", "options": ["China puts no batteries in its EVs", "Batteries are banned outside China", "China makes most of the world's cells"], "correctIndex": 2, "consequences": ["Every EV needs a battery.", "Batteries are made and sold worldwide.", "Over 80% of 2025 cells were made in China."], "explanation": "China made over 80% of battery cells in 2025, and its packs were the cheapest of any region."}, "proReasoning": "Where something is made at scale, it is often cheapest. Batteries follow that pattern.", "commonMistake": "Thinking price gaps are random.", "mentalModel": "Scale and price tend to go together."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:41442c139c99$ml$]::text[]),
($ml$c2fba452-5c4b-5664-9920-b309f12efbd0$ml$::uuid, $ml$ev$ml$, 3, 3, $ml${"id": "ev-d3-c3", "title": "Building a plant in America", "lessonTitle": "Who controls the EV supply chain", "slot": 3, "type": "decide", "brief": {"headline": "CATL installed 39.2% of all EV batteries in 2025, and China made over 80% of cells. The US taxes Chinese EVs at 100%; the EU added duties of up to 35.3%.", "kicker": "Decide: how do you secure cells for a US EV line?", "fullText": "You run battery sourcing for a carmaker building EVs in the US. Most cells in the world come from China, and CATL alone installed 39.2% of EV batteries in 2025.\n\nPolicy pushes back. The US raised its tariff on Chinese EVs to 100% in 2024, and the EU added duties of up to 35.3%. You can import cheaper cells and face political risk, or source closer to home and pay more. Either way, the cell makers hold the strongest hand.", "sources": [{"url": "https://cnevpost.com/2026/02/04/global-ev-battery-market-share-2025/", "label": "CnEVPost on SNE Research 2025 battery shares"}, {"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}, {"url": "https://www.whitecase.com/insight-alert/united-states-finalizes-section-301-tariff-increases-imports-china", "label": "White & Case, Section 301 tariffs"}, {"url": "https://trade.ec.europa.eu/access-to-markets/en/news/eu-commission-imposes-countervailing-duties-imports-battery-electric-vehicles-bevs-china", "label": "European Commission, EV countervailing duties"}]}, "evidence": {"kind": "buildChain", "prompt": "Order the steps of a careful sourcing plan.", "steps": ["Map where every cell in your EVs is made", "Check tariffs and rules for each source", "Qualify at least one source outside China", "Split volume between your sources", "Review the split as rules change"], "explanation": "Know your exposure, check the rules, add an alternative, then keep adjusting as policy moves."}, "numbers": {"kind": "numberSense", "prompt": "What tariff did the US set on Chinese EVs in 2024, in percent?", "min": 0, "max": 150, "value": 100, "unit": "%", "explanation": "100%, which doubles the price of an imported Chinese EV at the border."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked how a US carmaker should handle reliance on Chinese cells.", "prompt": "Which answer is most balanced?", "options": ["Add sources outside China over time", "Cut every Chinese supplier tomorrow", "Ignore tariffs and buy the cheapest"], "correctIndex": 0, "consequences": ["You reduce the risk without stopping production.", "Over 80% of cells come from China; cutting at once halts lines.", "A 100% tariff makes that plan costly."], "explanation": "With most cells made in China, cutting off overnight is impossible. Adding other sources step by step lowers the risk."}, "proReasoning": "Strong candidates avoid extremes. They reduce dependence gradually while keeping cars moving.", "commonMistake": "Proposing an instant cutoff from a supplier base that makes over 80% of cells.", "mentalModel": "Reduce dependence step by step."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker sources nearly all its cells from China and sells EVs in the US.", "prompt": "What is the main risk you price in?", "options": ["China making too few cells", "Tariffs or rules that raise its costs", "Cells suddenly becoming unnecessary"], "correctIndex": 1, "consequences": ["China makes over 80% of the world's cells.", "The US already taxes Chinese EVs at 100%.", "Every EV still needs cells."], "explanation": "Policy is the live risk. Tariffs and rules can raise the cost of Chinese supply quickly."}, "proReasoning": "Investors check where a company sells against where its cells come from. Policy sits between the two.", "commonMistake": "Treating supply chains as purely an engineering issue.", "mentalModel": "Map supply against the rules of each market."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup recycles EV batteries in the US into new cell materials.", "prompt": "What is your strongest pitch to carmakers?", "options": ["Cheaper than any Chinese cell", "A full replacement for new mining", "Local materials outside China's supply"], "correctIndex": 2, "consequences": ["Beating China on price is very hard.", "Recycling adds supply but cannot replace mining yet.", "Carmakers want sources that avoid tariffs and rules."], "explanation": "With tariffs high and China dominant, a domestic source of materials is valuable on its own."}, "proReasoning": "Founders frame local supply as risk reduction, which carmakers pay for when policy is tight.", "commonMistake": "Overpromising price or scale to win the first meeting.", "mentalModel": "Pitch reduced risk, not miracles."}, "curiosity": {"call": {"kind": "theCall", "situation": "You see few Chinese EVs on US roads, though China sells many abroad.", "prompt": "Which fact explains much of that?", "options": ["A 100% US tariff on Chinese EVs", "Chinese EVs cannot drive on US roads", "China sells no EVs abroad"], "correctIndex": 0, "consequences": ["The tariff doubles their price at the border.", "They meet safety rules in many other countries.", "Chinese brands sell widely outside the US."], "explanation": "The US raised its tariff on Chinese EVs to 100% in 2024, which prices most of them out."}, "proReasoning": "When a product is missing from a market, check the tariffs before the product.", "commonMistake": "Assuming absence means low quality.", "mentalModel": "Check the border before blaming the product."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5708dd940caf$ml$]::text[]),
($ml$c5e2e046-ec60-5cb0-81a1-7ecabaa18ec3$ml$::uuid, $ml$ev$ml$, 4, 1, $ml${"id": "ev-d4-c1", "title": "The country with no gas cars", "lessonTitle": "The numbers behind the EV shift", "slot": 1, "type": "apply", "brief": {"headline": "In 2025, 95.9% of new cars sold in Norway were fully electric. Worldwide the share was about one in four.", "kicker": "Apply it: what does one country tell you about the average?", "fullText": "Norway's new car sales were 95.9% fully electric in 2025. Tesla led for a fifth straight year with 19.1% of the market. Heavy registration fees and high fuel taxes make gas cars costlier to buy and run, and EVs long paid no VAT.\n\nThat is far above the world, where about one in four new cars was electric in 2025, and far above the US, where the share stayed under 10%. One country can sit at nearly 100% while the global average moves much more slowly.", "sources": [{"url": "https://insideevs.com/news/783304/norway-new-cars-fully-electric/", "label": "InsideEVs, Norway bought almost no gas cars"}, {"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each market by its 2025 EV share of new car sales.", "buckets": ["Over half", "Under half"], "items": [{"text": "Norway, at 95.9% fully electric", "bucket": 0}, {"text": "China, at nearly 55%", "bucket": 0}, {"text": "Europe as a whole, at 28%", "bucket": 1}, {"text": "The United States, under 10%", "bucket": 1}], "explanation": "Norway and China passed half. Europe overall and the US stayed well below."}, "numbers": {"kind": "numberSense", "prompt": "What share of Norway's new cars in 2025 were fully electric?", "min": 0, "max": 100, "value": 96, "unit": "%", "explanation": "95.9%. Fewer than 1 in 20 new cars had any other powertrain."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a carmaker's European team. They ask what Norway's 95.9% share means for the wider market.", "prompt": "Which answer avoids a common error?", "options": ["All of Europe will be 95% EV next year", "Norwegians simply like EVs more", "Norway is an outlier shaped by tax policy"], "correctIndex": 2, "consequences": ["Europe overall was at 28% in 2025.", "Taxes and fees made gas cars far costlier there.", "You link the share to fees and taxes, not to Europe overall."], "explanation": "Norway used taxes and fees to push EVs. Europe overall was at 28%, so Norway is not the average."}, "proReasoning": "Strong candidates explain an extreme number with its cause and keep it apart from the average.", "commonMistake": "Treating one market's record as the trend everywhere.", "mentalModel": "Explain outliers by their causes."}, "invest": {"call": {"kind": "theCall", "situation": "An EV maker says its sales will mirror Norway everywhere within a few years.", "prompt": "How do you judge that claim?", "options": ["Doubt it; Norway's policies are unusual", "Accept it; Norway proves the demand", "Ignore EV share in the forecast"], "correctIndex": 0, "consequences": ["Norway's share rests on fees, fuel taxes and VAT rules.", "Other markets lack the same incentives.", "EV share is a core input for EV sales forecasts."], "explanation": "Norway's share came with heavy taxes on gas cars. Without that policy, other markets move far more slowly."}, "proReasoning": "Investors ask what made a number happen before assuming it will repeat elsewhere.", "commonMistake": "Extrapolating a policy-driven market to the whole world.", "mentalModel": "Ask what made the number happen."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers EV fleet services. You want a market where nearly every new car is electric.", "prompt": "Where do you test first?", "options": ["A market with no EVs", "Norway", "The United States"], "correctIndex": 1, "consequences": ["No EVs means no customers for EV services.", "95.9% of new cars there were fully electric in 2025.", "The US share stayed under 10% in 2025."], "explanation": "Norway already lives in the future your product assumes, so you can learn faster there."}, "proReasoning": "Founders test where their product is already normal. Lessons from Norway can travel as other markets catch up.", "commonMistake": "Testing an EV service where few people drive EVs.", "mentalModel": "Test where your future already exists."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says one in four new cars worldwide is electric, so Norway must be about the same.", "prompt": "What's the more accurate picture?", "options": ["Norway is about 25%, like the world", "Norway sells mostly diesel cars", "Norway is near 96%, far above average"], "correctIndex": 2, "consequences": ["Norway's share was 95.9% in 2025.", "Fully electric cars were 95.9% of sales.", "Averages hide huge regional gaps."], "explanation": "The world average was about one in four, but Norway was at 95.9%. The average hides big gaps."}, "proReasoning": "Behind a global average, look for the extremes. They show what is possible and why.", "commonMistake": "Assuming every country sits near the average.", "mentalModel": "Averages hide extremes."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2f65cb69b1b8$ml$]::text[]),
($ml$c76030a7-5eb1-56cc-ad50-1cc4867e2c3e$ml$::uuid, $ml$ev$ml$, 4, 2, $ml${"id": "ev-d4-c2", "title": "Cheap batteries, big shares", "lessonTitle": "The numbers behind the EV shift", "slot": 2, "type": "connect", "brief": {"headline": "Packs in China averaged $84 per kWh in 2025, the cheapest anywhere, and nearly 55% of new cars sold there were electric. In the US, the share stayed under 10%.", "kicker": "Connect day 2 and day 4: battery prices and regional shares.", "fullText": "On day 2 you saw that battery cost decides who can make money, and packs in China averaged $84 per kWh in 2025, far below North America and Europe. On day 4 you saw the regional split: nearly 55% of new cars in China were electric, 28% in Europe and under 10% in the US.\n\nCheap packs make cheap EVs possible, and cheap EVs sell. Batteries are not the only reason, since policy matters too, but where packs are cheapest, EV shares tend to be highest.", "sources": [{"url": "https://about.bnef.com/insights/clean-transport/lithium-ion-battery-pack-prices-fall-to-108-per-kilowatt-hour-despite-rising-metal-prices-bloombergnef/", "label": "BloombergNEF battery price survey 2025"}, {"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "Which market had both cheaper packs and a higher EV share in 2025?", "left": {"name": "China", "note": "Packs at $84 per kWh"}, "right": {"name": "United States", "note": "Packs about 44% pricier"}, "correctIndex": 0, "explanation": "China had the cheapest packs and nearly 55% EV share. The US paid more and stayed under 10%."}, "numbers": {"kind": "numberSense", "prompt": "What share of new cars sold in Europe in 2025 were electric?", "min": 0, "max": 100, "value": 28, "unit": "%", "explanation": "28%, between China's nearly 55% and the US share of under 10%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why EV shares differ so much between China and the US.", "prompt": "Which answer covers the main drivers?", "options": ["Cheaper batteries plus different policy", "Chinese roads are shorter on average", "US drivers cannot charge at home"], "correctIndex": 0, "consequences": ["You name cost and policy, the two big levers.", "Road length does not explain a share gap this big.", "Many US drivers can charge at home."], "explanation": "China had the cheapest packs and strong policy support. Both helped push its share near 55%."}, "proReasoning": "Strong candidates give a two-part answer: cost and policy. Either alone misses half the story.", "commonMistake": "Naming one factor and ignoring the rest.", "mentalModel": "Cost and policy together explain most gaps."}, "invest": {"call": {"kind": "theCall", "situation": "You expect battery prices outside China to fall over time.", "prompt": "What might follow in those markets?", "options": ["No change, since price never matters", "Cheaper EVs and rising EV share", "EV share falling to zero"], "correctIndex": 1, "consequences": ["Price is a core driver of what people buy.", "Cheap packs helped China reach nearly 55%.", "Cheaper EVs make them easier to buy, not harder."], "explanation": "Where packs were cheapest, EV share was highest. Falling prices elsewhere could lift shares there too."}, "proReasoning": "Investors watch pack prices as a leading signal for where EV shares can rise next.", "commonMistake": "Treating EV share as fixed regardless of cost.", "mentalModel": "Cheaper packs pull EV share up."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells EV charging software. You must pick a first region to scale in.", "prompt": "Which region shows the most EVs on the road per new car sold?", "options": ["The US, under 10%", "Regions with no EV sales data", "China, at nearly 55%"], "correctIndex": 2, "consequences": ["A smaller share means fewer customers per car sold.", "No data makes the bet blind.", "More EVs sold means more chargers to manage."], "explanation": "China had the highest EV share, so charging software has the most cars to serve there."}, "proReasoning": "Founders follow the installed base. Charging software scales with the number of EVs actually sold.", "commonMistake": "Choosing a region by familiarity instead of market size.", "mentalModel": "Go where your users already are."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why EVs feel common in China but rare in many US towns.", "prompt": "Which pair of facts fits?", "options": ["Cheaper packs and a 55% share in China", "Equal prices and equal EV shares", "China banned new gas cars in 2025"], "correctIndex": 0, "consequences": ["Cheap batteries made EVs easier to buy there.", "Prices and shares differed a lot.", "Gas cars were still sold in China in 2025."], "explanation": "China had the cheapest packs and nearly 55% EV share. The US paid more and stayed under 10%."}, "proReasoning": "Price and share often move together. Check both before guessing at culture.", "commonMistake": "Explaining differences only by taste.", "mentalModel": "Look at price before taste."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c62bc34323f3$ml$]::text[]),
($ml$7523aeef-e28a-52c0-b657-1daea176089e$ml$::uuid, $ml$ev$ml$, 4, 3, $ml${"id": "ev-d4-c3", "title": "Where to launch next", "lessonTitle": "The numbers behind the EV shift", "slot": 3, "type": "decide", "brief": {"headline": "Global EV sales grew 20% in 2025 to over 20 million. Europe grew more than 30%, while the US share stayed under 10%. The IEA projects 23 million in 2026.", "kicker": "Decide: which region gets your next EV launch?", "fullText": "You plan launches for an EV maker with one new model ready. Electric car sales grew 20% worldwide in 2025, to more than 20 million, about one in four new cars. The IEA projects 23 million in 2026, or 28% of all car sales.\n\nThe growth was not even. Europe's EV sales grew more than 30% and reached a 28% share. The US share stayed under 10%. China was near 55%. Where you launch decides how much of that growth you can catch.", "sources": [{"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which region grew EV sales fastest in 2025?", "options": ["The US, under 10% share", "The world, at 20%", "Europe, over 30%"], "correctIndex": 2, "explanation": "Europe's EV sales grew more than 30%, faster than the 20% global rate."}, "numbers": {"kind": "numberSense", "prompt": "How many million EVs does the IEA project for 2026?", "min": 0, "max": 40, "value": 23, "unit": "M", "explanation": "About 23 million, or 28% of all car sales."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a strategy interview, you are asked where an EV maker should launch a new model in 2026.", "prompt": "Which answer uses the data well?", "options": ["Nowhere until growth is even", "Europe: fast growth, room to compete", "The US: biggest growth in 2025"], "correctIndex": 1, "consequences": ["Growth is never even; waiting means losing ground.", "Europe grew over 30% with a 28% share and room to gain.", "The US share stayed under 10% in 2025."], "explanation": "Europe combined fast growth with a share that still has room to rise. That makes it a strong launch market."}, "proReasoning": "Strong candidates weigh growth rate against how crowded a market is. Fast growth with room left beats a saturated leader.", "commonMistake": "Picking the biggest market without asking how crowded it is.", "mentalModel": "Weigh growth against crowding."}, "invest": {"call": {"kind": "theCall", "situation": "Two EV makers are similar. One sells mainly in Europe, the other mainly in the US.", "prompt": "Based on 2025, which had the stronger market tailwind?", "options": ["The US-focused maker", "Neither; markets do not matter", "The Europe-focused maker"], "correctIndex": 2, "consequences": ["The US share stayed under 10%.", "Where a company sells shapes its growth.", "Europe's EV sales grew more than 30% in 2025."], "explanation": "Europe grew fast in 2025 while the US lagged. Market mix shapes growth."}, "proReasoning": "Investors check where a company sells, because regional growth can carry or sink its numbers.", "commonMistake": "Comparing EV makers without looking at their markets.", "mentalModel": "Where a company sells shapes its growth."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds EV battery health checks for used car dealers. You have funding for one region.", "prompt": "Where is demand likely to grow fastest?", "options": ["Europe, with sales up over 30%", "A region where EV sales shrink", "Wherever your founders live"], "correctIndex": 0, "consequences": ["More new EVs today means more used EVs to check later.", "A shrinking market means fewer future customers.", "Home is convenient but not a market signal."], "explanation": "Fast new-car growth in Europe feeds the used market a few years later. That is where checks will be needed."}, "proReasoning": "Founders look a few steps ahead: today's new EV sales are tomorrow's used cars.", "commonMistake": "Choosing a region for convenience over growth.", "mentalModel": "Today's new cars are tomorrow's used market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A headline says global EV sales grew 20%. A friend assumes every country grew 20%.", "prompt": "What's the more accurate picture?", "options": ["EV sales fell in 2025", "Growth varied a lot by region", "Every country grew exactly 20%"], "correctIndex": 1, "consequences": ["Sales grew to more than 20 million.", "Europe grew over 30%; the US share stayed under 10%.", "A global rate averages very different markets."], "explanation": "The 20% global figure mixes Europe's 30%-plus growth with slower markets."}, "proReasoning": "A global growth rate is an average. The regions inside it can be far apart.", "commonMistake": "Reading a global rate as each country's rate.", "mentalModel": "Global rates average different stories."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:76ebce6d1028$ml$]::text[]),
($ml$f740c492-7174-51bc-875f-22f5609cd1e7$ml$::uuid, $ml$ev$ml$, 5, 1, $ml${"id": "ev-d5-c1", "title": "Canada's tariff U-turn", "lessonTitle": "The policies that steer EV sales", "slot": 1, "type": "apply", "brief": {"headline": "In January 2026, Canada cut its tariff on Chinese EVs from 100% to 6.1% for up to 49,000 cars a year. In return, China cut its canola tariff.", "kicker": "Apply it: how fast can one policy reopen a market?", "fullText": "On January 16, 2026, after Prime Minister Mark Carney met President Xi Jinping, Canada agreed to cut its tariff on Chinese EVs from 100% to the 6.1% most-favored-nation rate. The lower rate covers up to 49,000 cars a year, rising to about 70,000 by year five.\n\nChina agreed to cut its tariff on Canadian canola to about 15% by March 1, 2026. A US EV industry group warned that China had gained a foothold in North America. One trade deal changed which EVs can compete on price in Canada.", "sources": [{"url": "https://www.batterytechonline.com/industry-outlook/canada-cuts-china-ev-tariffs-in-policy-shift", "label": "Battery Technology, Canada cuts China EV tariffs"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the deal. Tap it.", "statements": ["The tariff fell from 100% to 6.1%.", "The lower rate covers any number of cars.", "China cut its tariff on Canadian canola."], "fakeIndex": 1, "explanation": "The 6.1% rate applies to up to 49,000 cars a year, rising to about 70,000 by year five."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand Chinese EVs a year can enter Canada at the 6.1% rate at first?", "min": 0, "max": 80, "value": 49, "unit": "K", "explanation": "Up to 49,000 a year, rising to about 70,000 by year five."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in a carmaker's Canada team. Your boss asks what the deal changes first.", "prompt": "Which answer is most precise?", "options": ["Up to 49,000 Chinese EVs pay just 6.1%", "All Chinese cars now enter tariff-free", "Canada banned Chinese EVs"], "correctIndex": 0, "consequences": ["You name the rate and the cap, the two terms that matter.", "The rate is 6.1% and only up to the quota.", "The deal opened the market rather than closing it."], "explanation": "The deal set a 6.1% rate for a capped number of cars. Knowing both terms tells you how much competition is coming."}, "proReasoning": "Strong analysts quote the exact terms of a policy: the rate, the cap and the timeline.", "commonMistake": "Summarizing a capped deal as fully open trade.", "mentalModel": "Quote the rate, the cap and the dates."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a carmaker selling mid-priced EVs in Canada.", "prompt": "What should you expect?", "options": ["No change, since quotas never bind", "More price competition from Chinese EVs", "Higher prices from less competition"], "correctIndex": 1, "consequences": ["A quota still lets tens of thousands of cars in.", "Up to 49,000 cheaper imports a year enter at 6.1%.", "More imports mean more competition, not less."], "explanation": "The deal lets tens of thousands of Chinese EVs in at a low tariff, adding price pressure on local rivals."}, "proReasoning": "Investors trace a tariff change to who gains and who faces new price pressure.", "commonMistake": "Ignoring trade policy when valuing a carmaker.", "mentalModel": "Lower tariffs mean new price pressure."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup services EVs in Canada. Chinese brands may now sell more cars there.", "prompt": "What is your best move?", "options": ["Refuse to work on Chinese EVs", "Wait for the quota to be removed", "Prepare to service the new brands"], "correctIndex": 2, "consequences": ["Turning them away hands the work to rivals.", "Waiting gives rivals a head start.", "New cars on the road need repairs and parts."], "explanation": "A policy shift brings new cars, and new cars need service. Early preparation wins those customers."}, "proReasoning": "Founders treat policy changes as market openings and move before rivals do.", "commonMistake": "Waiting for a policy to settle before acting.", "mentalModel": "Move when policy opens a door."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why Canada would cut EV tariffs while the US keeps them at 100%.", "prompt": "Which fact explains part of it?", "options": ["China cut its tariff on Canadian canola", "Canada builds no cars of its own", "The US asked Canada to cut tariffs"], "correctIndex": 0, "consequences": ["The deal traded EV access for canola access.", "Canada does build cars and parts.", "The article reports no US request."], "explanation": "The deal was a trade: lower EV tariffs for lower Chinese tariffs on Canadian canola."}, "proReasoning": "Trade deals swap access. Look for what each side got.", "commonMistake": "Assuming tariff cuts are one-sided gifts.", "mentalModel": "Ask what each side got."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:264047148c4a$ml$]::text[]),
($ml$2e8aa45d-4fcf-5fc1-ba24-fa85b14a36a7$ml$::uuid, $ml$ev$ml$, 5, 2, $ml${"id": "ev-d5-c2", "title": "Rules that make the money", "lessonTitle": "The policies that steer EV sales", "slot": 2, "type": "connect", "brief": {"headline": "Tesla earned about $2 billion in 2025 from regulatory credits sold to carmakers that miss emission targets. Ford's EV unit lost $4.8 billion that year.", "kicker": "Connect day 2 and day 5: policy as a revenue line.", "fullText": "On day 2 you saw where the money in an EV goes, including regulatory credits: carmakers that miss emission targets can buy credits from EV makers, and Tesla earned about $2 billion this way in 2025. On day 5 you saw how policy steers sales.\n\nThe credits are policy turned into revenue. They exist only because rules set emission targets. When rules ease, carmakers need fewer credits and the price falls. A business line built on a rule lasts only as long as the rule.", "sources": [{"url": "https://carboncredits.com/tesla-reports-first-ever-annual-revenue-drop-in-2025-carbon-credit-sales-also-dip-28", "label": "CarbonCredits.com on Tesla 2025"}, {"url": "https://s205.q4cdn.com/882619693/files/doc_financials/2025/q4/Ford-Q4-2025-Earnings-Press-Release.pdf", "label": "Ford Q4 2025 earnings"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how a regulatory credit earns money.", "steps": ["A rule sets an emission target", "A carmaker misses its target", "An EV maker has credits to spare", "The carmaker buys credits from it", "The EV maker books the sale as revenue"], "explanation": "The rule creates the shortfall, the shortfall creates the buyer, and the EV maker sells what it has spare."}, "numbers": {"kind": "numberSense", "prompt": "About how many billions did Tesla earn from regulatory credits in 2025?", "min": 0, "max": 5, "value": 2, "unit": "B", "explanation": "About $2 billion, from carmakers that needed credits to meet their targets."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an EV maker's finance team. They ask about credit revenue.", "prompt": "Which answer shows judgment?", "options": ["It comes from selling more cars abroad", "It depends on rules that can change", "It is permanent, like car sales"], "correctIndex": 1, "consequences": ["Credits are sold to other carmakers, not drivers.", "You flag that credit revenue rests on policy.", "Credits vanish if the rules behind them ease."], "explanation": "Credits exist because rules set targets. If rules ease, demand for credits falls."}, "proReasoning": "Strong candidates know which revenue lines depend on rules and treat them as less certain.", "commonMistake": "Treating credit revenue like ordinary product sales.", "mentalModel": "Policy revenue lasts as long as the policy."}, "invest": {"call": {"kind": "theCall", "situation": "An EV maker earns a large share of its profit from regulatory credits. Rules may ease.", "prompt": "What is the risk?", "options": ["Its cars stop working on the road", "Credits suddenly double in price", "Profit falls if credit demand dries up"], "correctIndex": 2, "consequences": ["Car function does not depend on credits.", "Easing rules lowers demand, not raises it.", "Looser rules mean fewer carmakers need to buy."], "explanation": "Credits sell only while others miss targets. Easier rules shrink that market."}, "proReasoning": "Investors strip out policy-dependent revenue to see the core business underneath.", "commonMistake": "Valuing credit income as if it were guaranteed.", "mentalModel": "Separate policy income from the core business."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your EV startup models revenue. A cofounder wants to count on selling credits for years.", "prompt": "How should you treat credit income?", "options": ["As upside, not the base plan", "As your main revenue for a decade", "As income that cannot change"], "correctIndex": 0, "consequences": ["You stay solvent even if rules ease.", "A rule change could erase it.", "Rules change, and credit demand with them."], "explanation": "Credit income depends on rules other people set. Plan the business to stand without it."}, "proReasoning": "Founders build plans that survive a rule change, and treat policy money as a bonus.", "commonMistake": "Building the base case on income a regulator can remove.", "mentalModel": "Treat policy money as upside."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn Tesla gets paid by other carmakers. A friend asks why rivals would pay Tesla.", "prompt": "What's the reason?", "options": ["They rent Tesla factories", "They buy credits to meet emission rules", "They pay Tesla to stop selling cars"], "correctIndex": 1, "consequences": ["Credits are about emissions, not factories.", "Missing a target costs them more than buying credits.", "Credits do not limit Tesla's sales."], "explanation": "Carmakers that miss emission targets can buy credits from EV makers like Tesla."}, "proReasoning": "Rules can create markets. Here, missing a target creates a buyer for credits.", "commonMistake": "Thinking rivals never pay each other.", "mentalModel": "Rules can turn rivals into customers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3fbecd1cb017$ml$]::text[]),
($ml$ec511791-d719-5184-b0ae-23b9dede2a81$ml$::uuid, $ml$ev$ml$, 5, 3, $ml${"id": "ev-d5-c3", "title": "Planning around a deadline", "lessonTitle": "The policies that steer EV sales", "slot": 3, "type": "decide", "brief": {"headline": "The US $7,500 EV credit ended on September 30, 2025. Sales hit a record 438,487 that quarter, then fell nearly 24% in the first half of 2026.", "kicker": "Decide: how do you plan stock around a policy deadline?", "fullText": "You run sales planning for an EV maker in the US. The federal credit of $7,500 for new EVs ended for purchases after September 30, 2025. Buyers rushed: third-quarter US EV sales hit a record 438,487.\n\nThen demand fell. In the first half of 2026, US EV sales were nearly 24% lower than a year earlier. Dealers who stocked up for the rush and kept ordering at the same pace were left with cars nobody was buying.", "sources": [{"url": "https://blog.turbotax.intuit.com/tax-reform/electric-vehicle-credits-are-ending-soon-under-the-one-big-beautiful-bill-what-you-need-to-know-125862/", "label": "TurboTax on the end of EV credits"}, {"url": "https://www.coxautoinc.com/insights-hub/q3-2025-ev-sales-report-commentary/", "label": "Cox Automotive, Q3 2025 EV sales"}, {"url": "https://www.moneytalksnews.com/where-the-u-s-ev-market-stands-a-year-after-trump-ended-tax-credits/", "label": "Money Talks News on US EV sales after the credit"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan fits a known credit deadline better?", "left": {"name": "Steady orders all year", "note": "Same pace before and after"}, "right": {"name": "Front-load, then cut back", "note": "More stock before, less after"}, "correctIndex": 1, "explanation": "Sales peaked before the deadline and dropped after. Matching stock to that curve avoids unsold cars."}, "numbers": {"kind": "numberSense", "prompt": "By about what percent did US EV sales fall in early 2026 versus a year earlier?", "min": 0, "max": 60, "value": 24, "unit": "%", "explanation": "Nearly 24%, after the record rush in the quarter before the credit ended."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in a sales ops interview how you'd plan around the end of a purchase credit.", "prompt": "Which plan shows you read the signal?", "options": ["Keep orders flat all year", "Cut stock before the deadline", "Stock up before, cut orders after"], "correctIndex": 2, "consequences": ["Flat orders leave cars unsold after the deadline.", "You miss the record rush before the credit ends.", "You match supply to the rush and the drop that follows."], "explanation": "Buyers rushed before September 30, 2025, then sales fell nearly 24%. Plan for both phases."}, "proReasoning": "Strong candidates plan for the pull-forward and the hangover that follows a policy deadline.", "commonMistake": "Treating a deadline rush as the new normal.", "mentalModel": "A deadline pulls sales forward, then leaves a gap."}, "invest": {"call": {"kind": "theCall", "situation": "An EV maker reports record sales in the quarter before a credit ended.", "prompt": "How do you read that record?", "options": ["Partly pulled forward; expect a drop", "Proof of lasting new demand for EVs", "Unrelated to the credit ending"], "correctIndex": 0, "consequences": ["US sales fell nearly 24% in early 2026.", "Much of the rush was buyers beating the deadline.", "The timing lines up with the deadline."], "explanation": "The record came right before the deadline and was followed by a sharp drop. Part of it was borrowed from later."}, "proReasoning": "Investors discount sales records that come right before a subsidy ends.", "commonMistake": "Extrapolating a deadline-driven record into the future.", "mentalModel": "Discount records set before a subsidy ends."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells EV chargers through dealers. The credit just ended and dealer orders are dropping.", "prompt": "What do you do?", "options": ["Wait for the credit to return", "Find buyers beyond new-car dealers", "Raise prices to make up the gap"], "correctIndex": 1, "consequences": ["There is no sign the credit is coming back.", "Existing EV owners and fleets still need chargers.", "Higher prices in a slump lose more sales."], "explanation": "New-car sales fell after the credit ended. Owners of the cars already sold are another market."}, "proReasoning": "Founders hit by a policy change find customers who do not depend on that policy.", "commonMistake": "Waiting for a subsidy to return.", "mentalModel": "Find demand that does not depend on the subsidy."}, "curiosity": {"call": {"kind": "theCall", "situation": "You notice US EV sales hit a record in late 2025, then dropped. A friend asks why.", "prompt": "What's the explanation?", "options": ["EVs were banned in early 2026", "Gas prices fell to almost nothing", "Buyers rushed before the credit ended"], "correctIndex": 2, "consequences": ["EVs stayed legal to sell.", "Gas prices did not vanish.", "The $7,500 credit ended after September 30, 2025."], "explanation": "People bought before the $7,500 credit ended, then sales fell nearly 24% in early 2026."}, "proReasoning": "When sales spike then drop, look for a deadline.", "commonMistake": "Reading a spike as a lasting trend.", "mentalModel": "Spikes often have deadlines behind them."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:791a33fd6f6e$ml$]::text[]),
($ml$c1c57b12-a168-521b-8679-416344752073$ml$::uuid, $ml$ev$ml$, 6, 1, $ml${"id": "ev-d6-c1", "title": "The solar car that stopped", "lessonTitle": "The EV startups that ran out of road", "slot": 1, "type": "apply", "brief": {"headline": "Lightyear began building its first solar EV in Finland in November 2022, planning 946 cars. Two months later, the unit making it went bankrupt.", "kicker": "Apply it: what sank a startup with thousands of orders?", "fullText": "Dutch startup Lightyear started production of the Lightyear 0 in Finland in November 2022, planning 946 units in all. The price had climbed to about €250,000, partly because of expensive parts.\n\nIn January 2023, Lightyear stopped production and let its operating company, Atlas Technologies, go bankrupt on January 27, putting over 620 jobs at risk. It said it would focus on a cheaper Lightyear 2 under €40,000, with about 21,000 fleet orders and over 40,000 people on a waiting list. Orders did not pay for the factory in time.", "sources": [{"url": "https://www.maakindustrie.nl/en/artikelen/werkmaatschappij-van-lightyear-is-failliet", "label": "Maakindustrie, Lightyear operating company bankrupt"}, {"url": "https://nltimes.nl/2023/01/24/solar-electric-automaker-lightyear-cancels-production-its-first-expensive-model", "label": "NL Times, Lightyear cancels production of its first model"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Lightyear story in order.", "steps": ["The Lightyear 0 price rises to about €250,000", "Production starts in Finland in November 2022", "Lightyear halts production of the first model", "Atlas Technologies goes bankrupt in January 2023", "Lightyear says it will focus on a car under €40,000"], "explanation": "A costly first car went into production, then cash ran short before volume came. The cheaper car became the hope."}, "numbers": {"kind": "numberSense", "prompt": "How many Lightyear 0 cars did the company plan to build in total?", "min": 0, "max": 3000, "value": 946, "explanation": "946 units. A tiny run of a very expensive car cannot fund a factory."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An EV startup with a famous concept car offers you a job. It has built only a few cars so far.", "prompt": "What do you ask first?", "options": ["How many people are on the waiting list", "How many months of cash it has left", "How many awards the car has won"], "correctIndex": 1, "consequences": ["Lightyear had over 40,000 on its list and still failed.", "Runway decides whether the job exists next year.", "Awards do not pay salaries or suppliers."], "explanation": "Lightyear had orders and a waiting list, yet its operating company went bankrupt. Cash against burn is the first question."}, "proReasoning": "Strong candidates ask about runway and the path to volume before the product. A waiting list is not cash.", "commonMistake": "Judging a startup by buzz and orders instead of cash.", "mentalModel": "Ask about runway before the product."}, "invest": {"call": {"kind": "theCall", "situation": "An EV startup shows 21,000 fleet orders and a waiting list of 40,000. It asks you for funding.", "prompt": "What do you weigh most?", "options": ["The size of the waiting list", "How beautiful the design is", "Cash needed to build cars at scale"], "correctIndex": 2, "consequences": ["A list is not a deposit, let alone revenue.", "Design wins attention, not survival.", "Building at scale is what drains startups before sales."], "explanation": "Lightyear had those very numbers and still ran out of cash. The cost of scaling decides survival."}, "proReasoning": "Investors convert orders into cash timing: when does each car bring money in versus when does the factory cost money?", "commonMistake": "Treating orders as revenue in hand.", "mentalModel": "Orders are not cash."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are designing your first EV. A costly halo car would get headlines; a cheaper car would sell more.", "prompt": "Which do you build first?", "options": ["The car you can sell in volume", "The €250,000 halo car", "Both at once to cover every buyer"], "correctIndex": 0, "consequences": ["Volume brings cash to fund the next step.", "Lightyear's costly first car ran out of runway.", "Two programs at once burn cash twice as fast."], "explanation": "Lightyear built a costly first car and went bankrupt before its cheaper model. Volume first buys time."}, "proReasoning": "Founders sequence products so early sales fund later ones. A tiny, costly first run rarely pays for a factory.", "commonMistake": "Starting with a showpiece that cannot bring in cash.", "mentalModel": "Lead with what sells in volume."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a startup with 40,000 people waiting for its car could go bankrupt.", "prompt": "What's the best explanation?", "options": ["The cars were given away to buyers", "Building cars costs money long before sales", "Nobody wanted a solar car at any price"], "correctIndex": 1, "consequences": ["The cars were priced at about €250,000.", "The factory and parts must be paid before cars earn.", "Thousands of fleet orders show interest existed."], "explanation": "Interest was real, but the company had to pay for production before it could sell enough cars."}, "proReasoning": "In car making, money goes out years before it comes in. Interest alone does not bridge that gap.", "commonMistake": "Assuming a waiting list protects a company.", "mentalModel": "Cash must last until sales arrive."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fe6f7f5af20c$ml$]::text[]),
($ml$9bba1dce-00fb-5ea5-9cd7-c9725e71712a$ml$::uuid, $ml$ev$ml$, 6, 2, $ml${"id": "ev-d6-c2", "title": "Who can afford to lose", "lessonTitle": "The EV startups that ran out of road", "slot": 2, "type": "connect", "brief": {"headline": "Nikola went bankrupt in February 2025 with $47 million left. Ford's EV unit lost $4.8 billion in 2025, and Ford kept going.", "kicker": "Connect day 2 and day 6: losses with and without a cushion.", "fullText": "On day 2 you saw Ford's segments: Model e lost $4.8 billion in 2025, while Ford Pro earned $6.8 billion and Ford Blue $3.0 billion. On day 6 you saw Nikola file for bankruptcy with $47 million in cash, after holding $200 million against $270 million of debt in late 2024.\n\nBoth lost money on EVs. The difference is what stood behind the loss. Ford's other businesses paid for its EV losses. Nikola had no other business, so its losses had nowhere to go.", "sources": [{"url": "https://s205.q4cdn.com/882619693/files/doc_financials/2025/q4/Ford-Q4-2025-Earnings-Press-Release.pdf", "label": "Ford Q4 2025 earnings"}, {"url": "https://electriccarsreport.com/2025/02/nikola-files-for-chapter-11-bankruptcy-joining-growing-list-of-fallen-ev-startups/", "label": "Electric Cars Report, Nikola joins fallen EV startups"}]}, "evidence": {"kind": "faceOff", "prompt": "Which company could absorb a big EV loss in 2025?", "left": {"name": "Ford", "note": "Gas and commercial units earned $9.8 billion"}, "right": {"name": "Nikola", "note": "$47 million in cash at its bankruptcy"}, "correctIndex": 0, "explanation": "Ford's profitable units covered Model e's loss. Nikola had nothing to fall back on."}, "numbers": {"kind": "numberSense", "prompt": "How many millions in cash did Nikola have when it filed for bankruptcy?", "min": 0, "max": 300, "value": 47, "unit": "$M", "explanation": "$47 million, a tiny fraction of the $4.8 billion Ford's EV unit lost in one year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have two offers: Ford's EV unit and an EV-only startup. Both lose money on EVs.", "prompt": "What is the key difference in job risk?", "options": ["The startup loses less, so it is safer", "There is no difference at all", "Ford has profitable units behind the loss"], "correctIndex": 2, "consequences": ["A smaller loss can still sink a firm with no backstop.", "What stands behind a loss decides survival.", "Ford Pro and Ford Blue earned $9.8 billion in 2025."], "explanation": "Ford could fund Model e from its other units. A startup with no other income cannot."}, "proReasoning": "Strong candidates ask who pays for the losses, not just how big they are.", "commonMistake": "Comparing losses without asking what funds them.", "mentalModel": "Ask what funds the loss."}, "invest": {"call": {"kind": "theCall", "situation": "You compare an EV startup's yearly loss with Ford's EV loss. The startup's is far smaller.", "prompt": "What should you check before calling it safer?", "options": ["Its cash compared with its burn", "Whether its logo is more modern", "How many models it has announced"], "correctIndex": 0, "consequences": ["Nikola filed with $47 million against heavy debts.", "Branding does not change cash burn.", "Announced models cost money before they earn."], "explanation": "A small loss can still be fatal if cash runs out. Nikola had $200 million against $270 million of debt."}, "proReasoning": "Investors compare cash to burn and debt. The absolute size of a loss says little on its own.", "commonMistake": "Judging risk by the size of the loss alone.", "mentalModel": "Compare cash to burn, not loss to loss."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your EV startup will lose money for years before profits. You have no other business.", "prompt": "What should you build alongside the car?", "options": ["A larger headquarters for the team", "A source of revenue that arrives sooner", "A second, costlier car program now"], "correctIndex": 1, "consequences": ["Offices cost money and earn none.", "Early revenue stretches your runway, like Ford's other units.", "A second program doubles the cash burn."], "explanation": "Ford survives EV losses because other units earn. A startup needs some income that arrives early."}, "proReasoning": "Founders look for a revenue line that pays sooner than car sales, such as services or parts.", "commonMistake": "Depending entirely on car sales years away.", "mentalModel": "Find income that arrives before the car does."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Ford can lose $4.8 billion on EVs while Nikola failed over far less.", "prompt": "What's the explanation?", "options": ["Ford sells every EV at a profit", "Nikola never lost money on trucks", "Ford earns money elsewhere to cover it"], "correctIndex": 2, "consequences": ["Model e lost $4.8 billion in 2025.", "Nikola ran down its cash and debt rose.", "Ford Pro alone earned $6.8 billion in 2025."], "explanation": "Ford's other businesses earned more than Model e lost. Nikola had no such cushion."}, "proReasoning": "A loss is survivable if something else pays for it.", "commonMistake": "Thinking the bigger loss is always the bigger danger.", "mentalModel": "A cushion makes losses survivable."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1f2329a6783a$ml$]::text[]),
($ml$b70b5906-6108-54e6-aef7-b532145c4252$ml$::uuid, $ml$ev$ml$, 6, 3, $ml${"id": "ev-d6-c3", "title": "The last 18 months", "lessonTitle": "The EV startups that ran out of road", "slot": 3, "type": "decide", "brief": {"headline": "Lordstown, Fisker, Canoo and Nikola all went bankrupt between 2023 and 2025. You run a young EV maker with 18 months of cash and one prototype.", "kicker": "Decide: where does your last runway go?", "fullText": "You lead a young EV maker. You have one working prototype, a few thousand reservations and 18 months of cash. Four US startups went bankrupt in about two years: Lordstown Motors in 2023, Fisker in 2024, Canoo in January 2025 and Nikola in February 2025.\n\nThe pattern was the same: years of spending on factories and models before enough cars sold. Your choice now is where to spend the time you have left.", "sources": [{"url": "https://electriccarsreport.com/2025/02/nikola-files-for-chapter-11-bankruptcy-joining-growing-list-of-fallen-ev-startups/", "label": "Electric Cars Report, Nikola joins fallen EV startups"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each move by its effect on your runway.", "buckets": ["Stretches cash", "Burns cash"], "items": [{"text": "Use an existing plant to build cars", "bucket": 0}, {"text": "Focus on one model that can sell", "bucket": 0}, {"text": "Build a giant new factory first", "bucket": 1}, {"text": "Announce three new models at once", "bucket": 1}], "explanation": "Borrowed capacity and focus save cash. A new factory and many models burned through the failed startups' runways."}, "numbers": {"kind": "numberSense", "prompt": "How many US EV startups on this list went bankrupt in about two years?", "min": 0, "max": 10, "value": 4, "explanation": "Four: Lordstown, Fisker, Canoo and Nikola."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are hired as chief of staff at this startup. The CEO asks for your top priority.", "prompt": "What do you push for?", "options": ["Get one model selling before cash runs out", "Hire a full team for a second model", "Start building the big dream factory"], "correctIndex": 0, "consequences": ["Revenue in 18 months is the only way to survive.", "A second model splits cash and attention.", "The failed startups spent on factories first."], "explanation": "The failed four spent on scale before sales. Focus on getting one car to buyers within the runway."}, "proReasoning": "Strong operators tie every priority to the cash date. Anything that does not bring sales before it is a risk.", "commonMistake": "Planning for the company you hope to be instead of the runway you have.", "mentalModel": "Tie every priority to the cash date."}, "invest": {"call": {"kind": "theCall", "situation": "This startup asks you for more money. Its plan includes a new factory and three models.", "prompt": "What do you require before investing?", "options": ["More concept cars for shows", "A leaner plan around one model", "An even bigger factory plan"], "correctIndex": 1, "consequences": ["Concepts cost money and sell nothing.", "Focus lowers the cash needed to reach sales.", "Bigger plans need more cash and more time."], "explanation": "The four bankruptcies came after heavy spending on scale. A narrower plan cuts the cash needed."}, "proReasoning": "Investors in young carmakers push for focus and borrowed capacity before funding new factories.", "commonMistake": "Funding a startup's full ambition before it proves one product.", "mentalModel": "Fund focus before scale."}, "build_startup": {"call": {"kind": "theCall", "situation": "An established carmaker offers to build your car in its plant for a fee per vehicle.", "prompt": "What do you do?", "options": ["Refuse and build your own plant", "Delay until you can afford both", "Take the deal and keep cash for sales"], "correctIndex": 2, "consequences": ["Your own plant could eat the whole runway.", "Waiting burns the 18 months you have.", "You pay per car instead of a huge upfront cost."], "explanation": "Paying per car turns a huge fixed cost into a cost that grows with sales."}, "proReasoning": "Founders turn fixed costs into costs that rise with sales whenever they can. It keeps runway long.", "commonMistake": "Insisting on owning everything before you sell anything.", "mentalModel": "Rent capacity until volume proves itself."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why so many EV startups failed even though EV sales grew.", "prompt": "What's the main reason?", "options": ["They ran out of cash before scaling", "Nobody bought EVs in those years", "EVs were banned in the US"], "correctIndex": 0, "consequences": ["Factories and models drained cash before sales came.", "EV sales grew worldwide during those years.", "EVs stayed legal everywhere in the US."], "explanation": "The market grew, but these startups spent years of cash before selling enough cars."}, "proReasoning": "A growing market does not save a company that runs out of cash first.", "commonMistake": "Assuming market growth guarantees every player survives.", "mentalModel": "Growth does not pay your bills in time."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5aabe7b648dd$ml$]::text[]),
($ml$c6780001-f4e2-5c5c-8e9e-57204d3dcfe8$ml$::uuid, $ml$ev$ml$, 7, 1, $ml${"id": "ev-d7-c1", "title": "The Bolt comes back on LFP", "lessonTitle": "Two battery recipes", "slot": 1, "type": "apply", "brief": {"headline": "The new Chevy Bolt starts at $28,995 with a 65 kWh LFP battery and 255 miles of range. Its cells were first imported from China.", "kicker": "Apply it: why did GM choose LFP for its cheapest EV?", "fullText": "GM brought back the Chevrolet Bolt for model year 2027. The launch edition costs $29,990 and a base LT model follows at $28,995. It uses a 65 kWh lithium iron phosphate, or LFP, battery, and GM quotes 255 miles of range. It charges from 10% to 80% in about 26 minutes.\n\nGM declined to name its cell supplier. The cells were first imported from China, with domestic sourcing planned later. Production was set to start at GM's plant in Kansas City in January 2026. For a car built to be cheap, the cheaper chemistry won.", "sources": [{"url": "https://insideevs.com/news/775172/2027-chevrolet-bolt-range-price-revealed/", "label": "InsideEVs, 2027 Chevy Bolt price and range"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why does LFP suit a car built to be among the cheapest EVs?", "options": ["It costs less and is good enough", "It holds the most energy per kilogram", "It needs no cells at all"], "correctIndex": 0, "explanation": "LFP is cheaper and offers enough range for most drivers. NMC holds more energy but costs more."}, "numbers": {"kind": "numberSense", "prompt": "How many miles of range does the new Bolt offer on its 65 kWh LFP pack?", "min": 0, "max": 400, "value": 255, "unit": "mi", "explanation": "255 miles, enough for most daily driving at a price under $30,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at GM. They ask why the new Bolt uses LFP instead of NMC.", "prompt": "Which answer shows you get the trade-off?", "options": ["LFP gives the longest range possible", "NMC is no longer sold anywhere", "Lower cost matters more than top range"], "correctIndex": 2, "consequences": ["NMC, not LFP, holds more energy per kilogram.", "NMC is still used where range matters most.", "A sub-$30,000 car needs the cheaper chemistry."], "explanation": "The Bolt aims to be cheap. LFP keeps the battery cost down and still gives 255 miles."}, "proReasoning": "Strong candidates match chemistry to the car's job: cheap and good enough for a budget EV, dense for long range.", "commonMistake": "Calling one chemistry best without saying best for what.", "mentalModel": "Match the chemistry to the car's job."}, "invest": {"call": {"kind": "theCall", "situation": "The Bolt's LFP cells came from China first, with US supply planned later.", "prompt": "What should you watch?", "options": ["Whether local cells keep the price low", "Whether LFP cells hold more energy", "Whether the Bolt name returns"], "correctIndex": 0, "consequences": ["Moving cell supply can raise costs on a cheap car.", "LFP holds less energy than NMC by design.", "The name already came back."], "explanation": "The Bolt's price depends on cheap LFP cells. Shifting supply away from China could change its cost."}, "proReasoning": "Investors follow where a cheap car's cells come from, because its margin is thin.", "commonMistake": "Ignoring supply plans on a low-margin product.", "mentalModel": "Thin margins make supply moves matter."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds small electric delivery vans for city routes under 150 miles a day.", "prompt": "Which chemistry do you pick?", "options": ["Whichever chemistry is newest", "LFP, for cost and durability", "NMC, for maximum range"], "correctIndex": 1, "consequences": ["New is not the same as right for the job.", "Short routes do not need NMC's extra energy.", "You pay for range your vans never use."], "explanation": "Short daily routes do not need top energy density. LFP gives enough range at a lower cost."}, "proReasoning": "Founders size the battery to the real duty cycle and pick the cheapest chemistry that covers it.", "commonMistake": "Buying more range than customers need.", "mentalModel": "Buy the range you need, not the most."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a new EV can cost under $30,000 when many cost far more.", "prompt": "Which battery fact helps?", "options": ["It has no battery pack", "Its battery is made of gold", "It uses cheaper LFP cells"], "correctIndex": 2, "consequences": ["Every EV needs a battery.", "Gold would make it far more costly.", "LFP uses iron and phosphate, not nickel and cobalt."], "explanation": "The Bolt uses LFP, a cheaper chemistry, which helps keep its price under $30,000."}, "proReasoning": "The battery is the biggest cost. A cheaper chemistry can move the price of the whole car.", "commonMistake": "Assuming cheap EVs must cut corners everywhere.", "mentalModel": "A cheaper chemistry makes a cheaper car."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0ab7d5599fbb$ml$]::text[]),
($ml$3238e6a0-e322-5c55-a6f1-10055e9cb2d9$ml$::uuid, $ml$ev$ml$, 7, 2, $ml${"id": "ev-d7-c2", "title": "The chemistry China leads", "lessonTitle": "Two battery recipes", "slot": 2, "type": "connect", "brief": {"headline": "LFP met nearly three-quarters of China's EV battery demand in 2024, and China made over 80% of the world's cells in 2025.", "kicker": "Connect day 3 and day 7: the winning chemistry and who makes it.", "fullText": "On day 3 you saw that China made over 80% of the world's battery cells in 2025, with CATL alone installing 39.2% of EV batteries. On day 7 you saw LFP reach nearly half the global EV battery market in 2024, and nearly three-quarters of demand in China.\n\nPut together, the cheaper chemistry is also the one China leads. Carmakers elsewhere that switch to LFP often buy from China or license Chinese know-how, as Ford did with CATL for its Michigan plant.", "sources": [{"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}, {"url": "https://cnevpost.com/2026/02/04/global-ev-battery-market-share-2025/", "label": "CnEVPost on SNE Research 2025 battery shares"}, {"url": "https://www.batterytechonline.com/ev-batteries/iea-report-lfp-dominates-as-ev-battery-prices-fall", "label": "Battery Technology, IEA report: LFP dominates"}, {"url": "https://www.ameslab.gov/news/ford-opening-michigan-plant-to-make-batteries-that-could-bring-ev-costs-down", "label": "Ames Lab on Ford's Michigan LFP plant"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["LFP met nearly three-quarters of China's 2024 demand.", "China made over 80% of battery cells in 2025.", "Ford invented its own LFP cell in Michigan."], "fakeIndex": 2, "explanation": "Ford's Michigan LFP plant uses technology licensed from CATL."}, "numbers": {"kind": "numberSense", "prompt": "What share of China's 2024 EV battery demand did LFP meet?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "Nearly three-quarters, and 80% in November and December."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what a shift to LFP means for a US carmaker's supply chain.", "prompt": "Which answer connects the dots?", "options": ["More reliance on Chinese LFP know-how", "Less need for any battery suppliers", "An end to battery imports"], "correctIndex": 0, "consequences": ["China leads LFP, so the switch often runs through it.", "LFP still needs cell makers and materials.", "Many LFP cells are still imported."], "explanation": "China leads both cell making and LFP. Switching chemistries can deepen that dependence."}, "proReasoning": "Strong candidates link a technical choice to its supply chain. Chemistry decides who you buy from.", "commonMistake": "Treating chemistry as a purely engineering decision.", "mentalModel": "A chemistry choice is a supplier choice."}, "invest": {"call": {"kind": "theCall", "situation": "LFP keeps gaining share. You compare a Chinese LFP cell maker with a Western NMC specialist.", "prompt": "Which trend favors the LFP maker?", "options": ["A sharp rise in cobalt use per cell", "Carmakers moving to the cheaper chemistry", "Buyers asking for the most range"], "correctIndex": 1, "consequences": ["LFP uses no cobalt at all.", "LFP reached nearly half the market in 2024.", "Long range favors NMC, not LFP."], "explanation": "As carmakers shift to LFP, its leading makers gain share."}, "proReasoning": "Investors watch chemistry shares, since a shift moves demand between suppliers.", "commonMistake": "Ignoring chemistry trends when picking battery stocks.", "mentalModel": "Chemistry shifts move supplier fortunes."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to make LFP cathode material outside China.", "prompt": "What is your strongest pitch?", "options": ["A brand new chemistry nobody uses", "Lower energy than today's LFP", "LFP supply that avoids China dependence"], "correctIndex": 2, "consequences": ["Unproven chemistry is a hard first sale.", "Lower performance is not a selling point.", "Carmakers want LFP without relying on one country."], "explanation": "LFP demand is huge and mostly served by China. A non-Chinese source fills a real gap."}, "proReasoning": "Founders find gaps where demand is big and supply is concentrated. LFP outside China is one.", "commonMistake": "Pitching novelty when buyers want a second source.", "mentalModel": "Fill the gap concentration leaves."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that many carmakers outside China are switching to LFP batteries.", "prompt": "Where does much of that LFP know-how come from?", "options": ["Chinese cell makers like CATL", "Gas engine makers in Detroit", "Phone screen factories"], "correctIndex": 0, "consequences": ["China leads LFP and licenses it abroad.", "Engine makers do not design battery cells.", "Screens and cells are different industries."], "explanation": "China leads LFP. Ford even licensed CATL technology for its Michigan plant."}, "proReasoning": "When a technology spreads, ask who it spreads from.", "commonMistake": "Assuming every country invents its own version.", "mentalModel": "Ask where the know-how starts."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a9f1c7d81aff$ml$]::text[]),
($ml$18f8e3e9-31c1-5ff9-9f5a-317892adcff9$ml$::uuid, $ml$ev$ml$, 7, 3, $ml${"id": "ev-d7-c3", "title": "Picking a battery for winter", "lessonTitle": "Two battery recipes", "slot": 3, "type": "decide", "brief": {"headline": "LFP took nearly half the global EV battery market in 2024 by being cheaper. NMC holds more energy, which helps long range and cold weather.", "kicker": "Decide: which chemistry for a long-range SUV sold in cold places?", "fullText": "You lead product for a carmaker planning a large SUV for buyers in cold northern markets who drive long distances.\n\nLFP, lithium iron phosphate, is cheaper and good enough for most EVs, and it reached nearly half the global EV battery market in 2024. NMC, nickel manganese cobalt, packs more energy into the same weight, which still matters for long range and cold climates. The right answer depends on the car's job.", "sources": [{"url": "https://www.batterytechonline.com/ev-batteries/iea-report-lfp-dominates-as-ev-battery-prices-fall", "label": "Battery Technology, IEA report: LFP dominates"}, {"url": "https://electronics360.globalspec.com/article/22873/from-nmc-to-lfp-batteries", "label": "Electronics360, from NMC to LFP batteries"}]}, "evidence": {"kind": "faceOff", "prompt": "Which chemistry fits a long-range SUV for cold markets?", "left": {"name": "LFP", "note": "Cheaper, very stable, less energy per kilogram"}, "right": {"name": "NMC", "note": "More energy per kilogram, better in cold"}, "correctIndex": 1, "explanation": "Long range and cold weather are where NMC's extra energy still pays off."}, "numbers": {"kind": "numberSense", "prompt": "About what share of the global EV battery market did LFP hold in 2024?", "min": 0, "max": 100, "value": 45, "unit": "%", "explanation": "Nearly half. NMC kept most of the rest, especially in long-range cars."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a product interview you are asked to choose a chemistry for this cold-climate SUV.", "prompt": "Which answer shows you match tech to the use?", "options": ["Either; chemistry makes no difference", "NMC, because range and cold matter here", "LFP, because it won half the market"], "correctIndex": 1, "consequences": ["Energy density and cold behavior differ a lot.", "You choose by the car's job, not by market share.", "Market share does not make LFP right for this use."], "explanation": "This SUV needs long range in cold weather, where NMC still has an edge."}, "proReasoning": "Strong candidates resist following the crowd. LFP leads overall, but NMC still wins specific jobs.", "commonMistake": "Picking the popular option without testing it against the use.", "mentalModel": "Choose for the job, not the trend."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker known for long-range cars in cold regions plans to keep using NMC.", "prompt": "How should you read that?", "options": ["A sign it ignores the market", "Proof LFP has failed", "A sensible fit for its buyers"], "correctIndex": 2, "consequences": ["Its buyers need what NMC does best.", "LFP still took nearly half the market.", "NMC still suits long range and cold climates."], "explanation": "NMC keeps an edge in range and cold weather. A cold-market, long-range brand has reason to stay with it."}, "proReasoning": "Investors judge choices against a company's customers, not against overall market share.", "commonMistake": "Treating every deviation from the trend as a mistake.", "mentalModel": "Judge choices against the customer."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes battery heating systems that help packs work in the cold.", "prompt": "Which customers likely need you most?", "options": ["Cold-market makers using LFP packs", "Makers selling only in warm cities", "Makers of gas-only cars"], "correctIndex": 0, "consequences": ["LFP is weaker in cold, so heating helps it most.", "Warm climates reduce the need for heating.", "Gas cars have no traction battery to heat."], "explanation": "NMC handles cold better, so LFP cars in cold markets have the clearest need for help."}, "proReasoning": "Founders look for the gap a popular technology leaves. LFP's cold weakness is a market.", "commonMistake": "Selling to customers who do not have the problem.", "mentalModel": "Sell to the weak spot of the popular choice."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear cheaper LFP batteries are taking over. A friend asks why some long-range cars still avoid them.", "prompt": "What's the reason?", "options": ["NMC costs less per kWh than LFP", "NMC holds more energy for long range", "LFP batteries are illegal in cars"], "correctIndex": 1, "consequences": ["LFP is the cheaper chemistry.", "More energy per kilogram means more range.", "LFP is widely used and legal."], "explanation": "NMC packs more energy into the same weight, which helps long range and cold weather."}, "proReasoning": "Every chemistry wins at something. Ask what the car needs most.", "commonMistake": "Thinking one battery is best for every car.", "mentalModel": "No battery is best for every car."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:51380dfa6a22$ml$]::text[]),
($ml$bf9ffedb-f2b1-5eb8-bac9-a34c8e75d10c$ml$::uuid, $ml$ev$ml$, 8, 1, $ml${"id": "ev-d8-c1", "title": "A mine that opened at the top", "lessonTitle": "Lithium's boom and bust", "slot": 1, "type": "apply", "brief": {"headline": "Core Lithium began selling spodumene from its Australian mine in February 2023. By January 2024 the price had fallen from about $8,000 a tonne to $950, and it stopped mining.", "kicker": "Apply it: what happens to a miner that starts at the peak?", "fullText": "Core Lithium opened its Grants open pit mine in Australia's Northern Territory in October 2022 and began selling spodumene concentrate, a lithium ore product, in February 2023.\n\nWithin a year the market turned. In early January 2024, spodumene sold for about $950 a tonne against about $8,000 a year earlier, and lithium carbonate was near $14,850 a tonne. Core suspended mining and switched to processing a stockpile of about 280,000 tonnes of ore.", "sources": [{"url": "https://www.mining.com/core-lithium-halts-mining-on-tough-market-conditions/", "label": "Mining.com, Core Lithium halts mining"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Core Lithium story in order.", "steps": ["The Grants mine opens in October 2022", "Spodumene sales begin in February 2023", "Spodumene prices fall to about $950 a tonne", "Core suspends mining in January 2024", "It processes its ore stockpile instead"], "explanation": "The mine opened near the peak and began selling as prices started to slide. Within a year mining stopped."}, "numbers": {"kind": "numberSense", "prompt": "Spodumene fell from about $8,000 to $950 a tonne. By roughly what percent?", "min": 0, "max": 100, "value": 88, "unit": "%", "explanation": "About 88%. The product Core was built to sell lost most of its value in a year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A lithium miner recruits you during a price boom, offering a big bonus.", "prompt": "What do you ask about?", "options": ["How the mine fares if prices crash", "How high prices could go next year", "How many trucks the mine owns"], "correctIndex": 0, "consequences": ["Core stopped mining within a year of first sales.", "Booms are when crashes are hardest to imagine.", "Equipment does not protect against falling prices."], "explanation": "Core began selling near the top and suspended mining a year later. Ask how the business survives low prices."}, "proReasoning": "Strong candidates ask about the downside in good times. Commodity jobs move with prices.", "commonMistake": "Joining at a peak without asking about a crash.", "mentalModel": "Ask about the bust during the boom."}, "invest": {"call": {"kind": "theCall", "situation": "A new lithium mine plans to start production when prices are at record highs.", "prompt": "What is the main risk?", "options": ["The mine finds too much ore", "Prices fall before it pays back", "Lithium stops being used in batteries"], "correctIndex": 1, "consequences": ["More ore is good unless prices collapse.", "Core opened near the top and halted within a year.", "Lithium is still central to EV batteries."], "explanation": "High prices attract new mines, and new supply helps push prices down. Late entrants can start right as the cycle turns."}, "proReasoning": "Investors ask where a project sits in the price cycle. Starting at the top is the riskiest time.", "commonMistake": "Valuing a new mine at peak prices.", "mentalModel": "Value a mine at a normal price, not the peak."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans a lithium processing plant. Your model uses this year's high price.", "prompt": "What do you change?", "options": ["Assume prices keep rising", "Skip the price question entirely", "Test the plan at much lower prices"], "correctIndex": 2, "consequences": ["Core opened assuming strong prices and halted.", "Price is the main driver of revenue.", "Spodumene fell about 88% in a year."], "explanation": "Commodity prices swing hard. A plan that works only at today's price is fragile."}, "proReasoning": "Founders in commodity businesses test their plan at the bottom of the cycle, not the top.", "commonMistake": "Building a plan around a single high price.", "mentalModel": "Plan for the low price."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear EV sales keep growing, yet a lithium mine shut down. A friend is puzzled.", "prompt": "What's the explanation?", "options": ["Prices crashed as new supply flooded in", "EVs stopped using lithium in cells", "The mine ran out of all its ore"], "correctIndex": 0, "consequences": ["Spodumene fell from about $8,000 to $950 a tonne.", "EV batteries still rely on lithium.", "Core still had about 280,000 tonnes stockpiled."], "explanation": "Demand grew, but supply grew faster and prices collapsed. Core stopped mining because selling did not pay."}, "proReasoning": "Price depends on supply as well as demand. Both can grow, at different speeds.", "commonMistake": "Assuming growing demand means rising prices.", "mentalModel": "Supply can outrun demand."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ca54b6a6ad29$ml$]::text[]),
($ml$65e45b66-3318-589e-bcbf-7911d3e12e6f$ml$::uuid, $ml$ev$ml$, 8, 2, $ml${"id": "ev-d8-c2", "title": "Cheaper metal, cheaper packs", "lessonTitle": "Lithium's boom and bust", "slot": 2, "type": "connect", "brief": {"headline": "Lithium fell more than 80% from 2022 to early 2024. By 2025, EV battery packs averaged $99 per kWh.", "kicker": "Connect day 2 and day 8: the metal price and the pack price.", "fullText": "On day 2 you saw that battery cost decides who can make money, with EV packs averaging $99 per kWh in 2025 and all packs falling 8% to $108. On day 8 you saw lithium fall from above $80,000 a tonne in 2022 to under $14,000 by February 2024.\n\nCheaper lithium helped push battery prices down, good news for carmakers. The same crash hurt miners: Piedmont Lithium cut 27% of its workforce. One company's input cost is another company's revenue.", "sources": [{"url": "https://about.bnef.com/insights/clean-transport/lithium-ion-battery-pack-prices-fall-to-108-per-kilowatt-hour-despite-rising-metal-prices-bloombergnef/", "label": "BloombergNEF battery price survey 2025"}, {"url": "https://finance.yahoo.com/news/crashing-lithium-prices-turn-the-industry-from-euphoria-to-despair-whats-next-184543769.html", "label": "Yahoo Finance, crashing lithium prices"}]}, "evidence": {"kind": "sortSignal", "prompt": "Who gained and who lost from cheaper lithium?", "buckets": ["Gained", "Lost"], "items": [{"text": "Carmakers buying battery packs", "bucket": 0}, {"text": "Battery makers buying lithium", "bucket": 0}, {"text": "Lithium miners selling ore", "bucket": 1}, {"text": "Refinery projects planned at the peak", "bucket": 1}], "explanation": "Buyers of lithium paid less. Sellers earned less, and projects planned at high prices were cut back."}, "numbers": {"kind": "numberSense", "prompt": "What was the average EV battery pack price per kWh in 2025, in dollars?", "min": 0, "max": 250, "value": 99, "unit": "$", "explanation": "$99 per kWh. All battery packs averaged $108 after an 8% drop."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a carmaker's purchasing team. They ask what the lithium crash meant for them.", "prompt": "Which answer is most precise?", "options": ["It had no effect on car costs", "It helped cut our battery pack costs", "It raised our battery costs sharply"], "correctIndex": 1, "consequences": ["Lithium is a key input to every pack.", "Cheaper lithium fed into lower pack prices.", "Falling metal prices lower costs, not raise them."], "explanation": "Lithium is a key battery input. Its crash helped bring EV packs down to $99 per kWh by 2025."}, "proReasoning": "Strong candidates trace an input price to the final product cost, step by step.", "commonMistake": "Treating raw material prices as someone else's problem.", "mentalModel": "Trace input prices into product costs."}, "invest": {"call": {"kind": "theCall", "situation": "Lithium prices crash. You own both a lithium miner and an EV maker.", "prompt": "What happens to each, all else equal?", "options": ["Both gain about the same from it", "Both suffer equally from the crash", "The miner suffers; the EV maker gains"], "correctIndex": 2, "consequences": ["Miners cut jobs and projects in the crash.", "They sit on opposite sides of the trade.", "Sellers earn less while buyers pay less."], "explanation": "The miner sells lithium and the EV maker effectively buys it. A crash moves them in opposite directions."}, "proReasoning": "Investors know which side of a commodity each holding sits on, and can hedge one with the other.", "commonMistake": "Assuming every EV-related stock moves together.", "mentalModel": "Know which side of the trade you own."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells battery packs to e-bike makers. Lithium just crashed.", "prompt": "What is your opportunity?", "options": ["Cut prices and win more customers", "Raise prices while costs fall", "Stop selling until prices rise"], "correctIndex": 0, "consequences": ["Lower costs let you sell for less and grow.", "Rivals will undercut you as costs fall.", "Stopping sales gives the market to rivals."], "explanation": "Cheaper inputs let you lower prices. In a competitive market, rivals will do the same."}, "proReasoning": "Founders pass input savings to customers to win share before rivals do.", "commonMistake": "Keeping prices high while costs fall in a competitive market.", "mentalModel": "Use falling costs to win share."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why EV batteries got cheaper even as demand grew.", "prompt": "Which fact explains part of it?", "options": ["Factories stopped paying workers", "Lithium prices fell more than 80%", "Batteries got smaller every year"], "correctIndex": 1, "consequences": ["Workers are still paid.", "A key input got much cheaper.", "Many packs actually grew in capacity."], "explanation": "Lithium fell from above $80,000 a tonne to under $14,000, pushing battery costs down."}, "proReasoning": "When a product gets cheaper, check its main raw materials.", "commonMistake": "Assuming growing demand always raises prices.", "mentalModel": "Cheaper inputs make cheaper products."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6c802ea2280c$ml$]::text[]),
($ml$73b3e8fa-737b-5315-8422-b9559854f2e7$ml$::uuid, $ml$ev$ml$, 8, 3, $ml${"id": "ev-d8-c3", "title": "Locking in the lithium price", "lessonTitle": "Lithium's boom and bust", "slot": 3, "type": "decide", "brief": {"headline": "Lithium in China went from above $80,000 a tonne in 2022 to under $14,000 by February 2024. You must sign a three-year supply deal for your cell plant.", "kicker": "Decide: fixed price or a price that follows the market?", "fullText": "You buy lithium for a battery cell plant and need a three-year supply contract. Lithium prices in China went from above $80,000 a tonne in 2022 to under $14,000 by February 2024, a fall of more than 80%.\n\nA fixed price gives certainty but can trap you if prices fall. A price linked to the market follows swings both ways. Albemarle and other miners cut spending when prices crashed. Whatever you sign, both sides of the deal will live with the cycle.", "sources": [{"url": "https://finance.yahoo.com/news/crashing-lithium-prices-turn-the-industry-from-euphoria-to-despair-whats-next-184543769.html", "label": "Yahoo Finance, crashing lithium prices"}]}, "evidence": {"kind": "faceOff", "prompt": "Which contract would have hurt a buyer who signed at the 2022 peak?", "left": {"name": "Fixed at the 2022 price", "note": "Above $80,000 a tonne for three years"}, "right": {"name": "Linked to the market", "note": "Falls when the market falls"}, "correctIndex": 0, "explanation": "A fixed peak price would have kept you paying over $80,000 while the market fell under $14,000."}, "numbers": {"kind": "numberSense", "prompt": "By February 2024, lithium in China was under how many thousand dollars a tonne?", "min": 0, "max": 100, "value": 14, "unit": "K", "explanation": "Under $14,000, down from above $80,000 in 2022."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a procurement interview you are asked how to buy lithium after this boom and bust.", "prompt": "Which answer shows judgment?", "options": ["Always lock the current price", "Buy only on the spot market", "Mix fixed and market-linked prices"], "correctIndex": 2, "consequences": ["Locking at a peak would have been costly.", "Spot only leaves you exposed to every spike.", "You keep some certainty without betting all on one price."], "explanation": "Prices swung over 80%. A blend limits the damage of being wrong in either direction."}, "proReasoning": "Strong buyers spread price risk rather than betting the whole contract on one direction.", "commonMistake": "Treating today's price as tomorrow's.", "mentalModel": "Spread price risk; do not bet one way."}, "invest": {"call": {"kind": "theCall", "situation": "A cell maker signed long fixed-price lithium deals in 2022. Prices then crashed.", "prompt": "What should you expect in its results?", "options": ["Higher costs than rivals buying now", "Lower costs than every rival has", "No effect at all from its contracts"], "correctIndex": 0, "consequences": ["It pays the old high price while rivals pay less.", "Fixed peak prices raise costs, not lower them.", "Contracts decide what it actually pays."], "explanation": "Fixed contracts signed near the top keep costs high while rivals buy at much lower prices."}, "proReasoning": "Investors read the terms of supply contracts, since they decide real costs for years.", "commonMistake": "Assuming every company pays the market price.", "mentalModel": "Contracts decide real costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your battery startup is small. A supplier offers a fixed three-year lithium price.", "prompt": "What do you push for?", "options": ["No contract at all", "A clause that adjusts if prices swing", "The fixed price with no changes"], "correctIndex": 1, "consequences": ["No contract leaves supply uncertain.", "You share the risk of big moves with the supplier.", "A crash could leave you overpaying for years."], "explanation": "Prices moved more than 80% in two years. A clause for big swings protects a small buyer."}, "proReasoning": "Founders negotiate for protection against extreme moves, which can sink a small company.", "commonMistake": "Signing a rigid price in a market that swings this hard.", "mentalModel": "Protect against extreme swings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why companies argue so much over lithium contracts.", "prompt": "What's the reason?", "options": ["Lithium price never changes", "Contracts are only for show", "Prices can swing more than 80%"], "correctIndex": 2, "consequences": ["It went from $80,000 to under $14,000.", "Contracts set real prices for years.", "The terms decide who wins or loses a swing."], "explanation": "With prices swinging this hard, the contract decides who carries the risk."}, "proReasoning": "Big price swings make contract terms worth fighting over.", "commonMistake": "Thinking raw materials have stable prices.", "mentalModel": "Volatile prices make terms matter."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:18abe129be11$ml$]::text[]),
($ml$76fedaaa-8dca-56a1-b3ae-05512c833ae2$ml$::uuid, $ml$ev$ml$, 9, 1, $ml${"id": "ev-d9-c1", "title": "A tariff on the anode", "lessonTitle": "China's graphite card", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, the US set a preliminary 93.5% anti-dumping duty on Chinese graphite anode material. US producers say the total tariff reaches about 160%.", "kicker": "Apply it: what happens when a country taxes the choke point?", "fullText": "In December 2024, a coalition of North American graphite producers asked the US to act against Chinese anode material. On July 17, 2025, the Commerce Department set a preliminary anti-dumping duty of 93.5%, covering natural and synthetic graphite and graphite inside finished batteries.\n\nThe producers calculate a combined rate of about 160% with other duties. The US relied entirely on imports for its graphite in 2024. A tax on the material that most anodes need raises the cost of every cell that uses it.", "sources": [{"url": "https://www.spglobal.com/energy/en/news-research/latest-news/metals/071725-us-determines-china-is-dumping-graphite-imposes-935-tariff", "label": "S&P Global, US sets 93.5% duty on Chinese graphite"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Who asked the US government for the graphite duty?", "options": ["US buyers of new electric cars", "North American graphite producers", "Chinese graphite exporters in Beijing"], "correctIndex": 1, "explanation": "A coalition of North American producers filed the petition in December 2024."}, "numbers": {"kind": "numberSense", "prompt": "What was the preliminary anti-dumping duty on Chinese anode graphite, in percent?", "min": 0, "max": 200, "value": 93.5, "unit": "%", "explanation": "93.5%, and about 160% combined with other duties, by the producers' count."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a US battery maker's supply team. Your boss asks what the duty means.", "prompt": "Which answer is most useful?", "options": ["Our costs will fall next year", "Chinese anode material gets far costlier", "Graphite is no longer needed in cells"], "correctIndex": 1, "consequences": ["A new tax raises costs, not lowers them.", "A 93.5% duty, about 160% combined, raises the import price.", "Most anodes still use graphite."], "explanation": "The US imported all its graphite in 2024, much of it from China. The duty makes that supply much more expensive."}, "proReasoning": "Strong analysts translate a trade ruling into its cost impact on the products they make.", "commonMistake": "Treating a duty as news rather than a cost change.", "mentalModel": "Turn trade news into cost impact."}, "invest": {"call": {"kind": "theCall", "situation": "The duty passes. You compare a North American graphite producer with a US cell maker importing Chinese graphite.", "prompt": "Who likely benefits?", "options": ["The cell maker importing from China", "Neither one is affected", "The North American graphite producer"], "correctIndex": 2, "consequences": ["Its main input now faces a 93.5% duty.", "A tariff this big shifts demand.", "Its rival imports just became far costlier."], "explanation": "The duty protects local producers and raises costs for importers of Chinese graphite."}, "proReasoning": "Investors map each trade ruling to winners and losers along the chain.", "commonMistake": "Assuming a tariff helps the whole domestic industry.", "mentalModel": "Every tariff has winners and losers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes synthetic graphite in the US. The duty just took effect.", "prompt": "What is your pitch to cell makers now?", "options": ["Local anode material without the duty", "The world's cheapest graphite ever", "Cells that need no anode"], "correctIndex": 0, "consequences": ["You avoid a 93.5% duty that imports now face.", "China long set the low price; beating it is hard.", "Mainstream cells still need an anode."], "explanation": "The duty makes Chinese graphite far costlier. A domestic source now competes on more than price."}, "proReasoning": "Founders move fast when policy shifts in their favor, before the window closes.", "commonMistake": "Overpromising price when the real edge is avoiding the duty.", "mentalModel": "Sell the edge policy gives you."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the US would tax graphite, a material in pencils.", "prompt": "What's the reason?", "options": ["Graphite is banned in US-made cars", "It is the main anode material in EV cells", "Pencils were getting far too cheap to make"], "correctIndex": 1, "consequences": ["Graphite sits inside nearly every EV cell.", "Most battery anodes are made of graphite.", "The duty targets battery anode material."], "explanation": "Graphite is the main anode material in lithium-ion cells, and China dominates its refining."}, "proReasoning": "A humble material can be strategic if every battery needs it.", "commonMistake": "Judging a material by its everyday uses.", "mentalModel": "Ordinary materials can be strategic."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:668822d197c5$ml$]::text[]),
($ml$b4b31232-e718-5ab0-91dd-1dcf8190128a$ml$::uuid, $ml$ev$ml$, 9, 2, $ml${"id": "ev-d9-c2", "title": "Two choke points", "lessonTitle": "China's graphite card", "slot": 2, "type": "connect", "brief": {"headline": "China made over 80% of battery cells in 2025, and it refines 90% of graphite into the high-purity form batteries need.", "kicker": "Connect day 3 and day 9: cells and the material inside them.", "fullText": "On day 3 you saw that China made over 80% of the world's battery cells in 2025. On day 9 you saw that it refines 90% of graphite into battery grade, and has required export licenses for sensitive grades since December 1, 2023.\n\nThat is two layers of the same chain. Even a carmaker that buys cells made outside China may find Chinese graphite inside them. Moving the factory does not always move the materials.", "sources": [{"url": "https://iea.org/reports/global-ev-outlook-2026/executive-summary", "label": "IEA, Global EV Outlook 2026"}, {"url": "https://www.techspot.com/news/100580-china-introduces-export-restrictions-graphite-essential-material-ev.html", "label": "TechSpot, China restricts graphite exports"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["China refines about 90% of battery-grade graphite.", "China has required graphite export licenses since 2023.", "Cells made outside China never use Chinese graphite."], "fakeIndex": 2, "explanation": "With China refining 90% of battery graphite, cells made elsewhere often still use it."}, "numbers": {"kind": "numberSense", "prompt": "What share of the world's natural graphite does China produce, in percent?", "min": 0, "max": 100, "value": 64, "unit": "%", "explanation": "64% of natural graphite, and it refines 90% into battery grade."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer says their cells come from Korea, so they have no China risk.", "prompt": "How do you respond?", "options": ["Korea refines all of its own graphite", "Modern cells contain no graphite", "The graphite inside may still be Chinese"], "correctIndex": 2, "consequences": ["China refines 90% of battery graphite.", "Most anodes are graphite.", "You show you know risk runs deeper than the cell."], "explanation": "Cell location is one layer. With China refining 90% of battery graphite, materials can still carry China risk."}, "proReasoning": "Strong candidates look past the first supplier to the materials inside.", "commonMistake": "Stopping at the country where the cell is assembled.", "mentalModel": "Look through the cell to the materials."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker claims a China-free supply chain because its cells are made in Europe.", "prompt": "What do you check?", "options": ["Where its anode graphite is refined", "The color of its battery packs", "How many dealers it has"], "correctIndex": 0, "consequences": ["China refines 90% of battery-grade graphite.", "Pack color reveals nothing about supply.", "Dealers have no link to material sources."], "explanation": "A European cell can still use Chinese graphite. Claims of independence need checking one layer down."}, "proReasoning": "Investors test supply chain claims at the material level, where concentration is highest.", "commonMistake": "Taking a China-free claim at face value.", "mentalModel": "Test claims at the material level."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup traces battery materials back to their source for carmakers.", "prompt": "Which risk makes your service valuable?", "options": ["Too many graphite refiners in the world", "Hidden Chinese graphite in non-Chinese cells", "Cells changing color as they age"], "correctIndex": 1, "consequences": ["Refining is concentrated, not crowded.", "Carmakers often cannot see what is inside their cells.", "Color is not a supply risk."], "explanation": "China refines 90% of battery graphite, so cells made elsewhere can still depend on it."}, "proReasoning": "Founders find value where buyers cannot see their own risk.", "commonMistake": "Solving a problem customers can already see.", "mentalModel": "Reveal the risk buyers cannot see."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that a battery was made in Hungary. A friend says that means no China link.", "prompt": "What's the more accurate picture?", "options": ["Hungary makes all its own graphite", "Batteries are made from local sand", "Its materials may still come from China"], "correctIndex": 2, "consequences": ["Graphite refining is concentrated in China.", "Cells need refined metals and graphite.", "China refines 90% of battery-grade graphite."], "explanation": "Where a cell is built and where its materials come from are different questions."}, "proReasoning": "Ask where the parts of a product come from, not just where it was assembled.", "commonMistake": "Treating the factory location as the whole story.", "mentalModel": "Assembly is only the last step."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7a352ec3e677$ml$]::text[]),
($ml$b147a22c-6fe6-5bd2-8ea0-4cbd3950f0fc$ml$::uuid, $ml$ev$ml$, 9, 3, $ml${"id": "ev-d9-c3", "title": "A second graphite source", "lessonTitle": "China's graphite card", "slot": 3, "type": "decide", "brief": {"headline": "China refines 90% of battery-grade graphite and has required export licenses since December 2023. A supplier outside China offers anode material at a higher price.", "kicker": "Decide: pay more for a second graphite source?", "fullText": "You run supply for a cell plant that buys almost all its graphite from China. China produces 64% of natural graphite, refines 90% of it into battery grade, and since December 1, 2023, requires export licenses for sensitive grades. A license rule lets it slow exports whenever it chooses.\n\nA supplier outside China offers anode material for part of your needs, at a higher price. Paying more cuts your margin. Not paying leaves your plant one license decision away from a shortage.", "sources": [{"url": "https://www.techspot.com/news/100580-china-introduces-export-restrictions-graphite-essential-material-ev.html", "label": "TechSpot, China restricts graphite exports"}]}, "evidence": {"kind": "buildChain", "prompt": "Order a careful response to the license rule.", "steps": ["Measure how much graphite comes from China", "Build a stock buffer of current supply", "Qualify the outside supplier's material", "Shift part of your volume to it", "Review the split as rules change"], "explanation": "Measure exposure, buy time with stock, test the alternative, then move volume step by step."}, "numbers": {"kind": "numberSense", "prompt": "What share of battery-grade graphite does China refine, in percent?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "About 90%, which is why its license rule matters to every cell maker."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO says the outside supplier costs too much and wants to stay fully on Chinese graphite.", "prompt": "What do you argue?", "options": ["A partial second source is insurance", "Switch everything to the new supplier now", "Ignore graphite; focus on lithium"], "correctIndex": 0, "consequences": ["You cap the cost while cutting the risk.", "A full switch costs most and is untested.", "Graphite is the choke point here."], "explanation": "Paying more on part of the volume limits the cost while protecting against a license squeeze."}, "proReasoning": "Strong operators frame a pricier backup as insurance with a known premium.", "commonMistake": "Arguing all or nothing when a partial shift solves most of the risk.", "mentalModel": "Frame backups as insurance."}, "invest": {"call": {"kind": "theCall", "situation": "Two cell makers look alike. One bought a second graphite source at a higher cost.", "prompt": "How do you compare them?", "options": ["Identical, since both make cells", "Lower margin, but lower supply risk", "Strictly worse, since costs are higher"], "correctIndex": 1, "consequences": ["Their exposure to one country differs.", "It pays more but is safer if licenses tighten.", "Higher cost buys protection from a squeeze."], "explanation": "The second source lowers margin today but protects output if China slows exports."}, "proReasoning": "Investors weigh margin against resilience. A cheaper supply chain can be the riskier one.", "commonMistake": "Rewarding the lowest cost without asking what risk it hides.", "mentalModel": "Weigh margin against resilience."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are the outside graphite supplier. The cell plant says your price is too high.", "prompt": "How do you win the deal?", "options": ["Demand they move all volume to you", "Cut your price below your cost", "Offer a smaller share as insurance"], "correctIndex": 2, "consequences": ["An all-or-nothing ask is likely refused.", "Selling below cost cannot last.", "A partial share is easier to approve and proves you out."], "explanation": "Buyers can justify a premium on part of their volume as insurance against China's license rule."}, "proReasoning": "Founders selling a pricier alternative start small and sell it as protection.", "commonMistake": "Trying to win the whole account at once.", "mentalModel": "Start as the backup, then grow."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would pay more for graphite from somewhere else.", "prompt": "What's the reason?", "options": ["To avoid relying on one country", "Because it is always better quality", "Because China stopped selling graphite"], "correctIndex": 0, "consequences": ["China refines 90% and can slow exports by license.", "Quality is not the main reason here.", "China licenses exports; it did not stop."], "explanation": "Paying more spreads the risk of depending on one country that controls exports."}, "proReasoning": "Sometimes the cheaper option carries a hidden cost: dependence.", "commonMistake": "Thinking the lowest price is always the best deal.", "mentalModel": "Cheap can hide dependence."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7e85a885fd3b$ml$]::text[]),
($ml$373f365d-367b-549b-b5a6-adf76b798aa2$ml$::uuid, $ml$ev$ml$, 10, 1, $ml${"id": "ev-d10-c1", "title": "LFP that goes 1,000 km", "lessonTitle": "Watt-hours per kilogram", "slot": 1, "type": "apply", "brief": {"headline": "In April 2024, CATL unveiled Shenxing Plus, an LFP pack with 205 Wh/kg at the system level. CATL said it could give over 1,000 km of range.", "kicker": "Apply it: what happens when cheap LFP gets denser?", "fullText": "CATL presented Shenxing Plus on April 25, 2024. It is an LFP battery, the cheaper chemistry, rated at 205 Wh per kilogram at the pack level, with packing efficiency up 7%.\n\nCATL called it the first LFP battery to exceed 1,000 km of range with 4C fast charging, adding about 600 km in ten minutes. Energy density was long NMC's advantage. If LFP packs keep closing the gap, the cheaper chemistry can take on longer-range cars.", "sources": [{"url": "https://www.electrive.com/2024/04/25/catl-presents-an-lfp-battery-enabling-a-1000-kilometre-range", "label": "electrive, CATL LFP battery with 1,000 km range"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What made Shenxing Plus notable among LFP batteries?", "options": ["Range once tied to NMC packs", "It used cobalt for more energy", "It was the first battery ever made"], "correctIndex": 0, "explanation": "LFP was known for lower energy density. A 205 Wh/kg pack with over 1,000 km of range moved it toward NMC territory."}, "numbers": {"kind": "numberSense", "prompt": "What energy density did CATL give for the Shenxing Plus pack, in Wh/kg?", "min": 0, "max": 350, "value": 205, "unit": "Wh/kg", "explanation": "205 Wh/kg at the system level, high for the LFP chemistry."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an engineering interview, you're asked what denser LFP means for NMC.", "prompt": "Which answer is most balanced?", "options": ["NMC disappears from cars next year", "Nothing changes for either one", "LFP can take more long-range cars"], "correctIndex": 2, "consequences": ["NMC still holds more energy at the top end.", "A 205 Wh/kg LFP pack shifts the trade-off.", "Closing the density gap widens LFP's reach."], "explanation": "Denser LFP narrows NMC's main advantage, so LFP can reach into longer-range models."}, "proReasoning": "Strong candidates describe shifts as moving boundaries, not sudden replacements.", "commonMistake": "Declaring a winner from one product launch.", "mentalModel": "New tech moves boundaries before it replaces."}, "invest": {"call": {"kind": "theCall", "situation": "Denser LFP packs keep arriving. You hold shares in a nickel miner.", "prompt": "What risk should you watch?", "options": ["Long-range cars moving to LFP", "LFP needing more nickel", "EV sales stopping"], "correctIndex": 0, "consequences": ["LFP uses no nickel, so each switch cuts demand.", "LFP uses iron and phosphate instead.", "EV sales were still growing."], "explanation": "NMC uses nickel; LFP does not. As LFP reaches longer-range cars, nickel demand from EVs can slow."}, "proReasoning": "Investors watch chemistry trends to see which metals gain or lose demand.", "commonMistake": "Assuming all EV growth helps every battery metal.", "mentalModel": "Chemistry decides which metals win."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds fast chargers. CATL says Shenxing Plus can add about 600 km in ten minutes.", "prompt": "What does that mean for you?", "options": ["Only NMC cars will need chargers", "More cars can use very fast charging", "Fast charging is no longer needed"], "correctIndex": 1, "consequences": ["This is an LFP pack built for fast charging.", "Batteries that take 4C charging need high-power stations.", "Faster-charging cars need more power, not less."], "explanation": "A pack that takes 4C charging needs stations that can deliver that power."}, "proReasoning": "Founders watch battery specs because they set what the rest of the ecosystem must deliver.", "commonMistake": "Ignoring battery advances that change customer needs.", "mentalModel": "Battery specs set charger needs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says LFP batteries are only for short-range city cars.", "prompt": "What's the more accurate picture?", "options": ["LFP cannot go past 100 km", "LFP is used only in phones and toys", "New LFP packs claim over 1,000 km"], "correctIndex": 2, "consequences": ["LFP cars commonly go far beyond that.", "LFP is widely used in EVs.", "CATL said Shenxing Plus exceeds 1,000 km."], "explanation": "LFP has been getting denser. CATL said its Shenxing Plus pack can give over 1,000 km."}, "proReasoning": "Battery reputations lag the technology. Check the latest numbers.", "commonMistake": "Judging a chemistry by its old limits.", "mentalModel": "Check the latest numbers, not old reputations."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eb6b6f80b78f$ml$]::text[]),
($ml$217f0ba1-0818-5c0e-9a9e-1784d437402b$ml$::uuid, $ml$ev$ml$, 10, 2, $ml${"id": "ev-d10-c2", "title": "Cycles, not just kilograms", "lessonTitle": "Watt-hours per kilogram", "slot": 2, "type": "connect", "brief": {"headline": "LFP cells last about 2,000 to 5,000 charge cycles, against 1,000 to 2,000 for NMC. LFP took nearly half the EV battery market in 2024.", "kicker": "Connect day 7 and day 10: why the cheaper recipe keeps winning.", "fullText": "On day 7 you saw LFP win nearly half the global EV battery market in 2024 by being cheaper and good enough. On day 10 you saw the numbers behind it: NMC cells store about 150 to 250 Wh per kilogram and LFP about 90 to 160, but LFP lasts about 2,000 to 5,000 cycles against 1,000 to 2,000 for NMC.\n\nLFP cells also cost about 20% to 30% less per kWh. For cars charged every day, cycle life and cost can matter more than the last bit of range.", "sources": [{"url": "https://www.batterytechonline.com/ev-batteries/iea-report-lfp-dominates-as-ev-battery-prices-fall", "label": "Battery Technology, IEA report: LFP dominates"}, {"url": "https://electronics360.globalspec.com/article/22873/from-nmc-to-lfp-batteries", "label": "Electronics360, from NMC to LFP batteries"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which chemistry wins on each number?", "buckets": ["LFP wins", "NMC wins"], "items": [{"text": "Charge cycles before wearing out", "bucket": 0}, {"text": "Cost per kWh", "bucket": 0}, {"text": "Heat stability before thermal runaway", "bucket": 0}, {"text": "Energy stored per kilogram", "bucket": 1}], "explanation": "LFP wins on cycles, cost and heat stability. NMC wins on energy per kilogram."}, "numbers": {"kind": "numberSense", "prompt": "At the top of its range, how many thousand charge cycles can an LFP cell last?", "min": 0, "max": 8, "value": 5, "unit": "K", "explanation": "Up to about 5,000, against up to about 2,000 for NMC."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why LFP gained share even though it holds less energy.", "prompt": "Which answer is most complete?", "options": ["Cheaper, longer-lived and good enough", "It holds more energy than NMC cells", "Regulators banned NMC cells in 2024"], "correctIndex": 0, "consequences": ["You cover cost, cycle life and sufficiency.", "NMC holds more energy per kilogram.", "NMC is still widely used."], "explanation": "LFP costs 20% to 30% less per kWh and lasts more cycles, while giving enough range for most cars."}, "proReasoning": "Strong candidates compare several numbers at once, not just the headline one.", "commonMistake": "Judging batteries on energy density alone.", "mentalModel": "Compare cost, life and density together."}, "invest": {"call": {"kind": "theCall", "situation": "A ride-hailing fleet company is choosing between LFP and NMC cars.", "prompt": "Which battery number matters most for its costs?", "options": ["The paint colors on offer", "Cycle life, since cars charge daily", "The top speed of each fleet car"], "correctIndex": 1, "consequences": ["Color has no effect on battery cost.", "More cycles means fewer battery replacements.", "Speed matters little to fleet economics."], "explanation": "Fleet cars charge constantly. LFP's 2,000 to 5,000 cycles mean the battery lasts longer."}, "proReasoning": "Investors in fleets value battery life highly, because replacement is a big cost.", "commonMistake": "Focusing on range when the business model rewards durability.", "mentalModel": "Match the metric to the business."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells home batteries that cycle every day for years.", "prompt": "Which chemistry fits best?", "options": ["NMC, for the lightest weight", "Whichever is most expensive", "LFP, for long life and stability"], "correctIndex": 2, "consequences": ["Weight matters little in a house.", "Price alone does not decide fit.", "Daily cycling rewards LFP's long life."], "explanation": "A home battery cycles daily and never moves. LFP's long life and heat stability fit that job."}, "proReasoning": "Founders match chemistry to duty: daily cycling and safety favor LFP.", "commonMistake": "Paying for energy density where weight does not matter.", "mentalModel": "Daily cycling favors long life."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why taxi fleets often like LFP batteries.", "prompt": "What's the reason?", "options": ["They last many more charge cycles", "They hold the most energy", "They never need any charging"], "correctIndex": 0, "consequences": ["LFP lasts about 2,000 to 5,000 cycles.", "NMC holds more energy per kilogram.", "Every EV battery needs charging."], "explanation": "Fleets charge daily, so LFP's longer cycle life saves money over time."}, "proReasoning": "For heavy use, how long a battery lasts can matter more than how far it goes.", "commonMistake": "Thinking range is the only battery number that matters.", "mentalModel": "Durability matters for heavy use."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:33509bbf37a5$ml$]::text[]),
($ml$b15a2de3-58f6-5efb-a952-d1d6c4adba76$ml$::uuid, $ml$ev$ml$, 10, 3, $ml${"id": "ev-d10-c3", "title": "Choosing cells for a delivery fleet", "lessonTitle": "Watt-hours per kilogram", "slot": 3, "type": "decide", "brief": {"headline": "LFP cells cost about 20% to 30% less per kWh than NMC and last 2,000 to 5,000 cycles. NMC holds more energy per kilogram but lasts 1,000 to 2,000 cycles.", "kicker": "Decide: which cells for vans that charge every night?", "fullText": "You run engineering for an electric delivery van used on city routes and charged every night. The vans must run for years.\n\nNMC cells store about 150 to 250 Wh per kilogram; LFP about 90 to 160. But LFP cells cost about 20% to 30% less per kWh, last about 2,000 to 5,000 cycles against 1,000 to 2,000 for NMC, and stay stable up to about 400°C, where NMC risks thermal runaway around 200°C. Every gain in one number costs you another.", "sources": [{"url": "https://electronics360.globalspec.com/article/22873/from-nmc-to-lfp-batteries", "label": "Electronics360, from NMC to LFP batteries"}]}, "evidence": {"kind": "faceOff", "prompt": "Which cells suit vans charged every night for years?", "left": {"name": "LFP", "note": "2,000 to 5,000 cycles, 20% to 30% cheaper"}, "right": {"name": "NMC", "note": "1,000 to 2,000 cycles, more energy per kg"}, "correctIndex": 0, "explanation": "Nightly charging for years rewards cycle life and low cost, which is where LFP wins."}, "numbers": {"kind": "numberSense", "prompt": "Charged once a night, about how many years would 3,000 cycles last?", "min": 0, "max": 20, "value": 8.2, "unit": "years", "explanation": "3,000 nights is about 8.2 years, beyond the low end of NMC's 1,000 to 2,000 cycles."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you're asked to justify a chemistry for these delivery vans.", "prompt": "Which answer uses the numbers best?", "options": ["Neither; vans should not use batteries", "LFP: more cycles and lower cost per kWh", "NMC: the most energy per kilogram"], "correctIndex": 1, "consequences": ["Electric vans run on batteries by design.", "You tie the choice to nightly charging and cost.", "City routes rarely need NMC's extra energy."], "explanation": "Daily charging over years rewards LFP's 2,000 to 5,000 cycles and lower cost."}, "proReasoning": "Strong candidates pick the metric that matches the duty cycle, then quote it.", "commonMistake": "Defaulting to energy density for every vehicle.", "mentalModel": "Quote the metric that matches the duty."}, "invest": {"call": {"kind": "theCall", "situation": "A van maker chose NMC for city delivery vans that charge nightly.", "prompt": "What cost risk should you flag?", "options": ["Too much cycle life", "Packs that cost too little", "Earlier battery replacement"], "correctIndex": 2, "consequences": ["NMC has fewer cycles, not more.", "NMC costs more per kWh, not less.", "NMC lasts 1,000 to 2,000 cycles versus LFP's higher range."], "explanation": "Nightly charging uses cycles fast. NMC's shorter life could mean costly replacements sooner."}, "proReasoning": "Investors check whether a product's battery choice fits how customers actually use it.", "commonMistake": "Ignoring replacement costs in fleet economics.", "mentalModel": "Check battery choice against real use."}, "build_startup": {"call": {"kind": "theCall", "situation": "A fleet customer asks your van startup for proof the battery will last.", "prompt": "What do you show them?", "options": ["Cycle life against their daily routes", "The top speed of the loaded van", "Your company logo and branding"], "correctIndex": 0, "consequences": ["Cycles per year shows how long the pack lasts.", "Speed says nothing about battery life.", "Logos prove nothing about durability."], "explanation": "Fleet buyers care how many years the pack lasts on their routes. Cycle life answers that."}, "proReasoning": "Founders translate battery specs into the customer's own terms: years of service on their routes.", "commonMistake": "Selling specs the customer does not care about.", "mentalModel": "Translate specs into the customer's terms."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a delivery company would pick a battery that holds less energy.", "prompt": "What's the reason?", "options": ["It never wears out at all", "It lasts longer and costs less", "It holds more energy than NMC"], "correctIndex": 1, "consequences": ["All batteries wear out eventually.", "LFP lasts more cycles and costs 20% to 30% less.", "NMC holds more energy per kilogram."], "explanation": "For vans charged nightly on short routes, cycle life and cost beat extra energy."}, "proReasoning": "In batteries, every gain in one number usually costs another. Pick the one that matters.", "commonMistake": "Assuming more energy is always better.", "mentalModel": "Pick the number that matters for the job."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:225ef5a12447$ml$]::text[]),
($ml$c6f72056-e365-5193-8c67-a8e5606aff9f$ml$::uuid, $ml$ev$ml$, 11, 1, $ml${"id": "ev-d11-c1", "title": "Hyundai's $900 million recall", "lessonTitle": "The recall that cost $1.9 billion", "slot": 1, "type": "apply", "brief": {"headline": "In February 2021, Hyundai recalled about 82,000 EVs worldwide over fire risk, at an expected cost of $900 million. All used LG cells.", "kicker": "Apply it: whose problem is a defect inside a supplier's cell?", "fullText": "Hyundai recalled about 82,000 electric vehicles worldwide: 75,680 Kona Electrics, 5,715 Ioniq Electrics and 305 city buses. More than a dozen Kona Electrics had caught fire. The expected cost was $900 million, called the most expensive EV recall to date.\n\nAll the affected vehicles used LG Chem battery cells, some or all made at LG's plant in Nanjing, China, between July 2017 and July 2019. Hyundai was in talks to split the cost with LG Energy Solution. The cells came from a supplier; the recall carried Hyundai's name.", "sources": [{"url": "https://www.greencarreports.com/news/1131385_hyundai-kona-electric-battery-packs-most-expensive-ev-recall", "label": "Green Car Reports, Kona Electric battery recall"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort the vehicles in the recall by type.", "buckets": ["Cars", "Buses"], "items": [{"text": "75,680 Hyundai Kona Electrics", "bucket": 0}, {"text": "5,715 Hyundai Ioniq Electrics", "bucket": 0}, {"text": "305 electric city buses", "bucket": 1}], "explanation": "Nearly all of the recall was cars. Every vehicle shared one thing: LG battery cells."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand vehicles did Hyundai recall worldwide?", "min": 0, "max": 200, "value": 82, "unit": "K", "explanation": "About 82,000, at an expected cost of $900 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join Hyundai's battery quality team after the recall. Your manager asks where to focus.", "prompt": "What should the team watch most closely?", "options": ["The supplier's cell production quality", "Paint quality on the finished cars", "The design of the car keys"], "correctIndex": 0, "consequences": ["The defect came from cells made at a supplier plant.", "Paint had nothing to do with the fires.", "Keys did not cause the recall."], "explanation": "The fires traced back to LG cells made in Nanjing. Quality checks must reach into the supplier's factory."}, "proReasoning": "Strong candidates know a carmaker's brand risk lives partly inside its suppliers' plants.", "commonMistake": "Treating supplier quality as the supplier's problem only.", "mentalModel": "Your brand risk lives in your suppliers."}, "invest": {"call": {"kind": "theCall", "situation": "Hyundai announces a $900 million recall. LG supplied the cells.", "prompt": "What decides how much Hyundai finally pays?", "options": ["The color of the recalled cars", "The cost split agreed with LG", "The number of dealers it has"], "correctIndex": 1, "consequences": ["Color has nothing to do with the bill.", "Supply terms decide who carries the bill.", "Dealer count does not set recall costs."], "explanation": "Hyundai and LG negotiated how to split the cost. That split decides each side's hit."}, "proReasoning": "Investors read recall news alongside supply contracts, which decide who pays.", "commonMistake": "Assuming the brand on the car pays the full recall.", "mentalModel": "Contracts decide who pays."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup inspects battery cells on the production line for hidden defects.", "prompt": "Who is your best first customer?", "options": ["A car wash chain with 40 sites", "A tire retailer near the plant", "A cell maker serving many carmakers"], "correctIndex": 2, "consequences": ["Car washes never see cell defects.", "Tires are unrelated to battery cells.", "One defect there can recall many brands at once."], "explanation": "Defects start at the cell plant. A cell maker supplying several carmakers has the most at stake."}, "proReasoning": "Founders sell where the problem starts, which is usually upstream of the brand.", "commonMistake": "Selling to the end of the chain when the fault starts at the start.", "mentalModel": "Sell where the problem starts."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Hyundai recalled cars if the fault was in someone else's cells.", "prompt": "What's the explanation?", "options": ["The carmaker answers for its cars", "LG builds the Hyundai cars", "Recalls only ever cover paint"], "correctIndex": 0, "consequences": ["Owners deal with the brand on the car.", "LG made the cells, not the cars.", "Recalls cover safety defects of any part."], "explanation": "Owners deal with the brand on the car, so Hyundai ran the recall even though LG made the cells."}, "proReasoning": "The name on the car takes responsibility, even for parts it buys.", "commonMistake": "Thinking suppliers face customers directly.", "mentalModel": "The brand answers for every part."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ac28ed2eba0a$ml$]::text[]),
($ml$2b83c49a-cd53-5b45-b6ee-9010b2f2b516$ml$::uuid, $ml$ev$ml$, 11, 2, $ml${"id": "ev-d11-c2", "title": "One supplier, two recalls", "lessonTitle": "The recall that cost $1.9 billion", "slot": 2, "type": "connect", "brief": {"headline": "GM recalled every Bolt over battery fires, and LG agreed to pay up to $2 billion. Hyundai recalled about 82,000 EVs. Both used LG cells.", "kicker": "Connect day 1 and day 11: one battery maker links two recalls.", "fullText": "On day 1 you learned to follow the battery: a few companies make most cells, so many carmakers share the same suppliers. On day 11 you saw GM recall more than 140,000 Chevrolet Bolts after 13 fires, with LG agreeing to reimburse GM $1.9 billion to $2 billion.\n\nIn the same year, Hyundai recalled about 82,000 EVs, with an expected cost of $900 million. Those also used LG cells. Rival carmakers, one supplier: a problem at a shared cell maker can hit several brands at once.", "sources": [{"url": "https://nbc24.com/news/nation-world/gm-reaches-deal-with-lg-to-pay-for-bolt-battery-recall-costs", "label": "GM reaches deal with LG on Bolt recall costs"}, {"url": "https://www.greencarreports.com/news/1131385_hyundai-kona-electric-battery-packs-most-expensive-ev-recall", "label": "Green Car Reports, Kona Electric battery recall"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The Bolt and the Kona Electric used LG cells.", "LG agreed to reimburse GM up to $2 billion.", "Each recall used cells from a different supplier."], "fakeIndex": 2, "explanation": "Both recalls traced back to LG cells. One supplier linked two rival brands."}, "numbers": {"kind": "numberSense", "prompt": "GM recalled more than how many thousand Bolts?", "min": 0, "max": 300, "value": 140, "unit": "K", "explanation": "More than 140,000, covering every Bolt sold since 2016."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what the Bolt and Kona recalls have in common.", "prompt": "Which answer shows the pattern?", "options": ["Both had faulty brakes", "Both used cells from the same supplier", "Both were built in the same factory"], "correctIndex": 1, "consequences": ["The fault was in the battery cells.", "You spot the shared supplier behind two brands.", "GM and Hyundai built them separately."], "explanation": "Both recalls traced to LG cells. Shared suppliers spread risk across rival brands."}, "proReasoning": "Strong candidates connect events across companies by following the supply chain.", "commonMistake": "Treating each recall as an isolated event.", "mentalModel": "Follow the battery across brands."}, "invest": {"call": {"kind": "theCall", "situation": "A big cell maker reports a defect. Several carmakers use its cells.", "prompt": "Which stocks might be hit?", "options": ["Only the supplier that made the cells", "Only the largest carmaker it serves", "The supplier and every carmaker it serves"], "correctIndex": 2, "consequences": ["Carmakers run the recalls and carry costs too.", "Smaller carmakers using the cells are exposed too.", "GM and Hyundai both recalled cars with LG cells."], "explanation": "A shared supplier spreads one defect across many brands, as LG's did with GM and Hyundai."}, "proReasoning": "Investors map which carmakers share a supplier, so one defect does not surprise them twice.", "commonMistake": "Assuming a supplier problem stays with the supplier.", "mentalModel": "Shared suppliers spread shared risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tracks which carmakers use which cell suppliers.", "prompt": "Which customer values that most?", "options": ["An insurer covering EV fleets", "A bakery chain downtown", "A gas station owner"], "correctIndex": 0, "consequences": ["A supplier defect can hit many insured cars at once.", "A bakery has no EV battery exposure.", "A gas station does not insure EVs."], "explanation": "One supplier defect can affect many brands. An insurer needs to know that hidden link."}, "proReasoning": "Founders sell hidden links to whoever carries the risk of them.", "commonMistake": "Selling data to people with no exposure to it.", "mentalModel": "Sell links to those who carry the risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how two rival carmakers had battery recalls the same year.", "prompt": "What's the link?", "options": ["Recalls happen purely by chance", "They used the same cell supplier", "They share one parent company"], "correctIndex": 1, "consequences": ["Both traced to the same supplier.", "Both used LG cells.", "GM and Hyundai are separate companies."], "explanation": "Both GM and Hyundai used LG cells. One supplier tied the two recalls together."}, "proReasoning": "When rivals share a problem, check whether they share a supplier.", "commonMistake": "Assuming coincidence when the supply chain explains it.", "mentalModel": "Shared problems often mean shared suppliers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:de37b53293e8$ml$]::text[]),
($ml$9c87099b-127d-5bcf-9946-5aceefb6bdf9$ml$::uuid, $ml$ev$ml$, 11, 3, $ml${"id": "ev-d11-c3", "title": "Who pays when cells fail", "lessonTitle": "The recall that cost $1.9 billion", "slot": 3, "type": "decide", "brief": {"headline": "GM counted 13 Bolt fires and recalled every Bolt sold since 2016. LG agreed to reimburse $1.9 billion to $2 billion. You are signing a new cell supply deal.", "kicker": "Decide: what goes in the recall clause?", "fullText": "You negotiate a cell supply contract for a carmaker. In 2021, GM recalled more than 140,000 Chevrolet Bolts after 13 fires, caused when a battery had two manufacturing defects at once. In October 2021, LG agreed to reimburse GM $1.9 billion to $2 billion.\n\nThirteen fires led to a recall of every Bolt sold. Rare failures can still force a full recall, and supply contracts decide who pays when cells fail. You must decide what your deal says.", "sources": [{"url": "https://nbc24.com/news/nation-world/gm-reaches-deal-with-lg-to-pay-for-bolt-battery-recall-costs", "label": "GM reaches deal with LG on Bolt recall costs"}]}, "evidence": {"kind": "buildChain", "prompt": "Order how a cell defect becomes a bill.", "steps": ["A defect slips through at the cell plant", "Cars catch fire on the road", "The carmaker recalls the model", "Both sides look at the supply contract", "The supplier pays its agreed share"], "explanation": "The defect starts at the supplier, the recall happens at the carmaker, and the contract decides the split."}, "numbers": {"kind": "numberSense", "prompt": "How many Bolt fires did GM count before the full recall?", "min": 0, "max": 60, "value": 13, "explanation": "13 fires led to recalling more than 140,000 cars."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks what clause matters most in the new cell contract.", "prompt": "What do you recommend?", "options": ["The font size of the contract", "A clause on office parking", "Clear terms on recall cost sharing"], "correctIndex": 2, "consequences": ["Formatting decides nothing about cost.", "Parking has nothing to do with defects.", "LG paid up to $2 billion under such terms."], "explanation": "The Bolt recall showed that contract terms decide who pays billions when cells fail."}, "proReasoning": "Strong negotiators spend time on low-chance, high-cost events like recalls.", "commonMistake": "Focusing only on unit price and ignoring failure terms.", "mentalModel": "Negotiate the rare, costly events."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker's new cell contract makes the supplier cover most recall costs.", "prompt": "How does that affect the carmaker's risk?", "options": ["It lowers its recall risk", "It raises its recall risk", "It has no effect at all"], "correctIndex": 0, "consequences": ["The supplier would carry most of a future bill.", "Shifting costs away lowers risk, not raises it.", "Who pays is the core of recall risk."], "explanation": "If the supplier covers most recall costs, the carmaker is less exposed, as GM was with LG."}, "proReasoning": "Investors look for recall cost terms, which can move billions between companies.", "commonMistake": "Ignoring contract terms when judging risk.", "mentalModel": "Contract terms move recall risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes cells. A carmaker wants you to cover 100% of any recall.", "prompt": "How do you respond?", "options": ["Refuse any recall terms at all", "Agree to a capped share tied to fault", "Accept unlimited liability for it"], "correctIndex": 1, "consequences": ["The carmaker will likely walk away.", "You stay in the deal without betting the company.", "One recall could cost more than you are worth."], "explanation": "A recall can cost billions. A capped share protects a small supplier while still winning the deal."}, "proReasoning": "Founders cap liabilities they could never survive, while accepting fair responsibility.", "commonMistake": "Signing unlimited liability to win a big customer.", "mentalModel": "Cap what could sink you."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why 13 fires led to recalling every Bolt ever sold.", "prompt": "What's the reason?", "options": ["Every Bolt had already caught fire", "Recalls cover only a few cars", "Any car could carry the same defect"], "correctIndex": 2, "consequences": ["Only 13 fires were counted.", "This one covered every Bolt since 2016.", "GM could not tell which batteries had both defects."], "explanation": "The fires happened when two defects appeared together. Any Bolt might have them, so all were recalled."}, "proReasoning": "If you cannot tell which items are faulty, you recall them all.", "commonMistake": "Thinking recalls only cover the cars that failed.", "mentalModel": "Unknown faults mean full recalls."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d209d23c5619$ml$]::text[]),
($ml$da72d472-7b18-55a2-ac6f-0ad2da8f19d3$ml$::uuid, $ml$ev$ml$, 12, 1, $ml${"id": "ev-d12-c1", "title": "1,205 km on one charge", "lessonTitle": "The solid-state promise", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, a Mercedes EQS test car with solid-state cells drove 1,205 km from Stuttgart to Malmö without charging. It still had 137 km left.", "kicker": "Apply it: how far is a road test from mass production?", "fullText": "At the end of August 2025, Mercedes-Benz drove an EQS test vehicle 1,205 km from Stuttgart, Germany, to Malmö, Sweden, without a charging stop. It arrived with 137 km of range left.\n\nThe lithium-metal cells come from US company Factorial Energy. Mercedes said usable energy rose 25% over the standard EQS battery at a similar size and weight. Mercedes aims to bring such innovations into series production by the end of the decade. One record drive is not millions of cars.", "sources": [{"url": "https://group.mercedes-benz.com/innovations/drive-systems/electric/eqs-solid-state-battery.html", "label": "Mercedes-Benz, EQS with solid-state battery"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Mercedes say about series production of this battery?", "options": ["It has no plans to produce it", "It aims for the end of the decade", "It started selling them in 2025"], "correctIndex": 1, "explanation": "Mercedes aims to bring innovations like this into series production by the end of the decade."}, "numbers": {"kind": "numberSense", "prompt": "After 1,205 km without charging, how many km of range did the car have left?", "min": 0, "max": 400, "value": 137, "unit": "km", "explanation": "137 km, after driving from Stuttgart to Malmö on one charge."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a battery startup. They ask what the Mercedes test proves.", "prompt": "Which answer is most careful?", "options": ["Solid-state has failed for good", "It works; scale is still unproven", "Solid-state cars are now on sale"], "correctIndex": 1, "consequences": ["The car drove 1,205 km on one charge.", "You credit the test without overstating it.", "Mercedes targets production by decade's end."], "explanation": "A road test shows the cells work. Making them cheaply by the million is still ahead."}, "proReasoning": "Strong candidates separate a demonstration from a product. Both matter, but they are not the same.", "commonMistake": "Treating a record drive as proof of mass production.", "mentalModel": "A demo is not a product."}, "invest": {"call": {"kind": "theCall", "situation": "Factorial's cells power a record drive. You consider investing in solid-state makers.", "prompt": "What is the main risk left?", "options": ["Whether the cells store any energy", "Whether cars need batteries", "Making the cells cheaply at scale"], "correctIndex": 2, "consequences": ["The test showed 25% more usable energy.", "EVs need batteries by definition.", "Lab and test results are not mass production."], "explanation": "The drive proved the cells can work. Cost-effective mass production is the open question."}, "proReasoning": "Investors in new battery tech focus on manufacturing scale and cost, where most ventures stall.", "commonMistake": "Valuing a company on a lab or test result alone.", "mentalModel": "Price the scale-up risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes equipment for producing battery cells.", "prompt": "How could solid-state progress help you?", "options": ["New cells need new production tools", "It ends all demand for cell tools", "It changes nothing for factories"], "correctIndex": 0, "consequences": ["Scaling new cells is a production problem.", "Every cell type still needs factories.", "New chemistry often needs new processes."], "explanation": "The hard part of solid-state is mass production. That creates demand for new manufacturing tools."}, "proReasoning": "Founders find opportunity in the bottleneck of a new technology, often manufacturing.", "commonMistake": "Assuming a new battery only matters to battery makers.", "mentalModel": "Sell to the bottleneck."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says solid-state EVs that go 1,200 km are available now.", "prompt": "What's the more accurate picture?", "options": ["No such drive ever happened at all", "A test car did it; sales come later", "You can buy one at any dealer now"], "correctIndex": 1, "consequences": ["The 1,205 km drive happened in 2025.", "Mercedes aims for production by decade's end.", "It was a test vehicle, not a car on sale."], "explanation": "A Mercedes test car drove 1,205 km. Series production is targeted for the end of the decade."}, "proReasoning": "Ask whether a battery record came from a test car or a car you can buy.", "commonMistake": "Assuming every record is already on sale.", "mentalModel": "Test car first, showroom later."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9a5e2532a0f7$ml$]::text[]),
($ml$b635319c-dc02-5847-8c4a-e536d3120b1f$ml$::uuid, $ml$ev$ml$, 12, 2, $ml${"id": "ev-d12-c2", "title": "Breaking the trade-off", "lessonTitle": "The solid-state promise", "slot": 2, "type": "connect", "brief": {"headline": "NMC cells store more energy but risk thermal runaway around 200°C. Solid-state cells aim to be safer and longer-lasting, and Mercedes saw 25% more usable energy.", "kicker": "Connect day 10 and day 12: can one battery win on every number?", "fullText": "On day 10 you saw that every gain in one battery number usually costs another. NMC stores about 150 to 250 Wh per kilogram but risks thermal runaway around 200°C; LFP is stable to about 400°C but holds less energy.\n\nOn day 12 you met solid-state batteries, which replace the liquid in today's cells with a solid material. The goal is safer, longer-lasting cells. Mercedes reported 25% more usable energy at a similar size and weight in a test car. If it scales, it could ease the trade-off.", "sources": [{"url": "https://electronics360.globalspec.com/article/22873/from-nmc-to-lfp-batteries", "label": "Electronics360, from NMC to LFP batteries"}, {"url": "https://www.batteriesinternational.com/2025/10/16/sumitomo-toyota-agree-all-solid-state-cathode-materials-plan/", "label": "Batteries International, Sumitomo and Toyota solid-state plan"}, {"url": "https://group.mercedes-benz.com/innovations/drive-systems/electric/eqs-solid-state-battery.html", "label": "Mercedes-Benz, EQS with solid-state battery"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each claim by its source.", "buckets": ["Today's cells", "Solid-state goal"], "items": [{"text": "NMC risks thermal runaway around 200°C", "bucket": 0}, {"text": "LFP holds less energy per kilogram", "bucket": 0}, {"text": "A solid electrolyte replaces the liquid", "bucket": 1}, {"text": "25% more usable energy in a similar pack", "bucket": 1}], "explanation": "Today's chemistries trade energy against stability. Solid-state aims to improve both."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did usable energy rise in the solid-state EQS test car?", "min": 0, "max": 100, "value": 25, "unit": "%", "explanation": "25% over the standard EQS battery, at a similar size and weight."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why carmakers care so much about solid-state batteries.", "prompt": "Which answer is most complete?", "options": ["They are far cheaper to make today", "They need no lithium of any kind", "They aim for more energy and safety"], "correctIndex": 2, "consequences": ["Cost-effective production is still unsolved.", "The Mercedes cells are lithium-metal.", "That would ease the trade-off between today's chemistries."], "explanation": "Today you choose energy or stability. Solid-state aims to offer more of both."}, "proReasoning": "Strong candidates frame new tech against the trade-off it tries to break.", "commonMistake": "Claiming solid-state is already cheaper.", "mentalModel": "Explain new tech by the trade-off it targets."}, "invest": {"call": {"kind": "theCall", "situation": "A company claims its solid-state cells beat NMC on energy and LFP on safety.", "prompt": "What should you ask for?", "options": ["Evidence of cost at production volume", "More photos of the test car", "A bigger launch event in Berlin"], "correctIndex": 0, "consequences": ["Cheap mass production is the open question.", "Photos show nothing about cost.", "Events do not prove manufacturing."], "explanation": "Breaking the trade-off in a test is a start. Doing it at a competitive cost is the real hurdle."}, "proReasoning": "Investors push past performance claims to production cost, where most battery bets succeed or fail.", "commonMistake": "Accepting performance data as proof of a business.", "mentalModel": "Ask for cost at volume."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup tests battery safety. Solid-state cells are coming to market.", "prompt": "What service should you prepare?", "options": ["Nothing, since new cells are always safe", "Safety tests designed for solid-state cells", "Tests only for gas engines"], "correctIndex": 1, "consequences": ["Safety must be proven, not assumed.", "New chemistry needs new validation.", "Gas engines are not your market here."], "explanation": "Safety is a key promise of solid-state. Makers will need to prove it with new tests."}, "proReasoning": "Founders prepare services the next technology will need to prove its claims.", "commonMistake": "Assuming a safer chemistry needs no testing.", "mentalModel": "Help new tech prove its claims."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what is special about solid-state batteries.", "prompt": "What's the core idea?", "options": ["They run on solar power only", "They contain no electrodes", "A solid replaces the liquid inside"], "correctIndex": 2, "consequences": ["They are batteries, not solar panels.", "Every battery has electrodes.", "That is the change the name refers to."], "explanation": "Solid-state batteries replace the liquid electrolyte with a solid material, aiming for safer, longer-lasting cells."}, "proReasoning": "Names often describe the key change. Solid-state means the electrolyte is solid.", "commonMistake": "Guessing at meaning without the basics.", "mentalModel": "The name points to the change."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:46cd46c01df6$ml$]::text[]),
($ml$0cb37d80-a011-59be-aa93-da23090493c1$ml$::uuid, $ml$ev$ml$, 12, 3, $ml${"id": "ev-d12-c3", "title": "Betting on 2028", "lessonTitle": "The solid-state promise", "slot": 3, "type": "decide", "brief": {"headline": "Toyota aims to launch EVs with all-solid-state batteries in 2027 or 2028, and is still working on cost-effective mass production.", "kicker": "Decide: do you design your 2028 car around solid-state?", "fullText": "You lead planning for a carmaker launching a new EV in 2028. Toyota aims to launch all-solid-state EVs in 2027 or 2028. In October 2025, Toyota and Sumitomo Metal Mining agreed to jointly develop a durable cathode material for them.\n\nThe companies are still working on performance, quality, safety and cost-effective mass production. Lab results are not mass production. Designing around a battery that may slip could delay your car; ignoring it could leave you behind.", "sources": [{"url": "https://www.batteriesinternational.com/2025/10/16/sumitomo-toyota-agree-all-solid-state-cathode-materials-plan/", "label": "Batteries International, Sumitomo and Toyota solid-state plan"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan protects a 2028 launch better?", "left": {"name": "Design only for solid-state", "note": "Best case if it arrives on time"}, "right": {"name": "Design for both cell types", "note": "Launches either way"}, "correctIndex": 1, "explanation": "Mass production is unproven. A design that can take today's cells launches even if solid-state slips."}, "numbers": {"kind": "numberSense", "prompt": "Joint research began around 2021. About how many years before a 2027 launch is that?", "min": 0, "max": 15, "value": 6, "unit": "years", "explanation": "About six years of research before the earliest target, and mass production is still being solved."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO wants the 2028 car to depend entirely on solid-state cells.", "prompt": "What do you advise?", "options": ["Keep a fallback with today's cells", "Go all in on solid-state cells", "Cancel the 2028 car entirely"], "correctIndex": 0, "consequences": ["You protect the launch if production slips.", "One delay could stop the whole car.", "Canceling throws away the program."], "explanation": "Toyota is still solving mass production. A fallback keeps your launch safe."}, "proReasoning": "Strong advisers back new tech while hedging the schedule against it slipping.", "commonMistake": "Betting a whole launch on an unproven supply.", "mentalModel": "Back new tech, hedge the schedule."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker tells investors its 2028 lineup depends on solid-state cells.", "prompt": "What risk do you flag?", "options": ["Batteries that cost nothing", "Delays if mass production slips", "Too much range for buyers"], "correctIndex": 1, "consequences": ["New cells will not be free.", "Production at scale is still unsolved.", "Extra range is not the risk here."], "explanation": "Toyota itself is still working on mass production. Depending on it adds schedule risk."}, "proReasoning": "Investors discount plans that rely on technology not yet made at scale.", "commonMistake": "Treating a target date as a delivery date.", "mentalModel": "A target date is not a delivery date."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup designs battery packs. A client wants packs ready for solid-state cells.", "prompt": "What do you offer?", "options": ["A pack only for solid-state cells", "A pack with no cells inside", "A pack that fits both cell types"], "correctIndex": 2, "consequences": ["Your design fails if solid-state slips.", "A pack needs cells to work.", "The client launches whatever cells arrive."], "explanation": "Solid-state timing is uncertain. A flexible pack keeps your client covered."}, "proReasoning": "Founders sell flexibility when the technology timeline is uncertain.", "commonMistake": "Designing only for a future that may arrive late.", "mentalModel": "Sell flexibility in uncertain times."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why solid-state batteries take so long when they work in labs.", "prompt": "What's the main reason?", "options": ["Cheap mass production is hard", "Nobody wants better batteries", "They only work at night time"], "correctIndex": 0, "consequences": ["Cost-effective mass production is still open.", "Carmakers invest heavily in them.", "Time of day has no effect."], "explanation": "Toyota and Sumitomo are still working on cost-effective mass production methods."}, "proReasoning": "A breakthrough counts only when it can be made by the million.", "commonMistake": "Assuming lab success means products soon.", "mentalModel": "Scale is the hard part."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:10fe03453d01$ml$]::text[]),
($ml$305b763d-7d24-51d7-a2f6-240b08172d99$ml$::uuid, $ml$ev$ml$, 13, 1, $ml${"id": "ev-d13-c1", "title": "Hyundai's dedicated platform", "lessonTitle": "One platform, many cars", "slot": 1, "type": "apply", "brief": {"headline": "In December 2020, Hyundai Motor Group unveiled E-GMP, a platform built only for EVs. It planned 23 battery-electric models by 2025, 11 of them on dedicated platforms.", "kicker": "Apply it: why build one base for many EVs?", "fullText": "Hyundai Motor Group revealed its Electric-Global Modular Platform, E-GMP, on December 2, 2020. It promised over 500 km of range on a charge, charging to 80% in 18 minutes and about 100 km of range in five minutes, with 800V charging as standard.\n\nThe group planned 23 battery-electric models by 2025, including 11 dedicated ones, starting with the IONIQ 5 in 2021, and aimed to sell over 1 million BEVs worldwide by 2025. One base designed around the battery would carry many cars across Hyundai and Kia.", "sources": [{"url": "https://www.hyundai.com/worldwide/en/newsroom/detail/0000000812", "label": "Hyundai, dedicated EV platform E-GMP"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What makes E-GMP a dedicated EV platform?", "options": ["It was designed around the battery", "It was adapted from a gas car", "It is used for one model only"], "correctIndex": 0, "explanation": "E-GMP was built only for EVs and shared across many models, unlike a converted gas platform."}, "numbers": {"kind": "numberSense", "prompt": "How many minutes did Hyundai say E-GMP needs to charge to 80%?", "min": 0, "max": 60, "value": 18, "unit": "min", "explanation": "18 minutes, with 800V charging standard on the platform."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Kia. They ask why the group built E-GMP instead of converting gas platforms.", "prompt": "Which answer shows you get it?", "options": ["Gas platforms are illegal for EVs", "It lets each car use a different battery", "A battery-first base avoids compromises"], "correctIndex": 2, "consequences": ["Some early EVs did use converted platforms.", "The point is to share batteries and parts.", "You name the core reason for dedicated platforms."], "explanation": "Converted gas platforms compromise on battery space and layout. A dedicated base avoids that and can be shared."}, "proReasoning": "Strong candidates explain both the design benefit and the cost benefit of a shared platform.", "commonMistake": "Thinking a platform is just a frame.", "mentalModel": "Battery-first design, shared across many cars."}, "invest": {"call": {"kind": "theCall", "situation": "Hyundai plans many models on one EV platform. You weigh what that means for profit.", "prompt": "What is the main financial upside?", "options": ["Development cost spread over many cars", "Every car can be priced the same", "No need for batteries"], "correctIndex": 0, "consequences": ["One base for many models lowers cost per car.", "Prices still differ by model.", "EVs still need batteries."], "explanation": "Sharing one platform spreads development cost across many models, lowering the cost per car."}, "proReasoning": "Investors look at how many models share a platform. More models mean lower cost per car.", "commonMistake": "Ignoring platform sharing when comparing EV makers' costs.", "mentalModel": "More models per platform, lower cost per car."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes EV parts. Hyundai will use one platform across many models.", "prompt": "Why is that good for you?", "options": ["Platforms end the need for parts", "One win can supply many models", "You must redesign for every car"], "correctIndex": 1, "consequences": ["Platforms still need parts.", "A part on the platform rides on every model.", "Shared platforms reduce redesign."], "explanation": "A part designed into the shared platform ships in every car built on it."}, "proReasoning": "Founders aim to get designed into platforms, where one win multiplies across models.", "commonMistake": "Pitching one model at a time when the platform is the real decision.", "mentalModel": "Win the platform, win every model."}, "curiosity": {"call": {"kind": "theCall", "situation": "You notice the IONIQ 5 and Kia EV6 charge alike. A friend asks why.", "prompt": "What's the reason?", "options": ["They are the same car with two names", "Kia buys IONIQ 5s and repaints them", "They share the E-GMP platform"], "correctIndex": 2, "consequences": ["They have different bodies and designs.", "Kia builds its own models.", "Shared base, shared battery systems and charging."], "explanation": "Both sit on E-GMP, which shares the battery, motors and charging setup."}, "proReasoning": "Different cars can share a base. The platform decides much of how they behave.", "commonMistake": "Assuming cars from one group share nothing.", "mentalModel": "Different bodies, shared base."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2ecfe29f2e50$ml$]::text[]),
($ml$d5f18665-4693-524d-89d7-958715c84811$ml$::uuid, $ml$ev$ml$, 13, 2, $ml${"id": "ev-d13-c2", "title": "Spreading the cost", "lessonTitle": "One platform, many cars", "slot": 2, "type": "connect", "brief": {"headline": "By June 2023, Volkswagen Group had built 1 million EVs on its MEB platform. Battery cost decides who can make money; shared platforms cut the rest.", "kicker": "Connect day 2 and day 13: where platforms save money.", "fullText": "On day 2 you saw that the battery decides who can make money, with EV packs averaging $99 per kWh in 2025. On day 13 you saw how platforms help with the rest of the car: Volkswagen's MEB carried 1 million EVs by June 2023 across five brands and eight factories.\n\nA platform shares the battery, motors and electronics across many models. The battery still decides much of the cost, but sharing everything else spreads development cost over many more cars.", "sources": [{"url": "https://about.bnef.com/insights/clean-transport/lithium-ion-battery-pack-prices-fall-to-108-per-kilowatt-hour-despite-rising-metal-prices-bloombergnef/", "label": "BloombergNEF battery price survey 2025"}, {"url": "https://newsio.com/2023/06/16/volkswagen-group-hits-1-million-mark-in-meb-based-ev-production-milestone/?amp=1", "label": "Newsio, VW Group hits 1 million MEB EVs"}]}, "evidence": {"kind": "sortSignal", "prompt": "What does a shared platform share across models?", "buckets": ["Shared", "Differs by model"], "items": [{"text": "The battery system", "bucket": 0}, {"text": "The motors and electronics", "bucket": 0}, {"text": "The body shape", "bucket": 1}, {"text": "The brand badge", "bucket": 1}], "explanation": "The platform shares the costly core. The body and badge give each brand its look."}, "numbers": {"kind": "numberSense", "prompt": "How many brands built cars on MEB by June 2023?", "min": 0, "max": 15, "value": 5, "explanation": "Five brands, from Volkswagen and Audi to Škoda and Cupra, in eight factories."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how Volkswagen lowered the cost of its EVs beyond the battery.", "prompt": "Which answer is best?", "options": ["One platform shared across brands", "Cheaper paint on every model", "Fewer seats in each car"], "correctIndex": 0, "consequences": ["MEB spread its cost over 1 million cars.", "Paint is a small share of cost.", "Seats barely move EV cost."], "explanation": "MEB shared its core parts across five brands, spreading development cost over 1 million cars."}, "proReasoning": "Strong candidates name the battery first, then platforms as the next biggest lever.", "commonMistake": "Focusing on small cost items.", "mentalModel": "Battery first, platform second."}, "invest": {"call": {"kind": "theCall", "situation": "Two carmakers sell 500,000 EVs each. One uses one platform; the other uses four.", "prompt": "Which likely has lower cost per car?", "options": ["Both cost exactly the same", "The one with one shared platform", "The one with four platforms"], "correctIndex": 1, "consequences": ["Platform count changes cost per car.", "One platform spreads development over more cars.", "Four platforms split the volume four ways."], "explanation": "The same volume on one platform spreads development cost further."}, "proReasoning": "Investors divide volume by platform count to see how well costs are spread.", "commonMistake": "Comparing only total volume.", "mentalModel": "Volume per platform drives cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans three EV models with very different bodies.", "prompt": "How do you keep costs down?", "options": ["Give each model its own platform", "Launch only the most costly model", "Build all three on one platform"], "correctIndex": 2, "consequences": ["Three platforms triple the cost.", "The costliest model sells fewest units.", "One base spreads your development cost."], "explanation": "Sharing one platform across models is how MEB spread its cost over 1 million cars."}, "proReasoning": "Founders design one platform first, then vary the bodies.", "commonMistake": "Designing each model from scratch.", "mentalModel": "One base, many bodies."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend notices a Volkswagen and a Škoda EV feel alike to drive.", "prompt": "What's the reason?", "options": ["They share the MEB platform", "They are the same factory model", "Škoda copies Volkswagen"], "correctIndex": 0, "consequences": ["MEB shares the battery, motors and electronics.", "They have different bodies and brands.", "Both are Volkswagen Group brands."], "explanation": "Both brands build on MEB, so much of what you feel comes from the same base."}, "proReasoning": "Brands in one group often share the base under the body.", "commonMistake": "Thinking similar feel means copying.", "mentalModel": "Shared base, similar feel."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:75f2caf4d675$ml$]::text[]),
($ml$c37974ec-432f-52cd-8bc1-c4237c2fc004$ml$::uuid, $ml$ev$ml$, 13, 3, $ml${"id": "ev-d13-c3", "title": "Convert or start fresh?", "lessonTitle": "One platform, many cars", "slot": 3, "type": "decide", "brief": {"headline": "Some early EVs sat on platforms made for gas cars. Volkswagen's dedicated MEB platform carried five brands and 1 million EVs by June 2023.", "kicker": "Decide: convert your gas platform or build a dedicated one?", "fullText": "You plan a carmaker's first three EVs. Converting your existing gas platform is faster, but some early EVs built that way compromised on battery space and layout.\n\nA dedicated EV platform is designed around the battery from the start, and different bodies sit on the same shared base. Volkswagen unveiled MEB in 2018 and built 1 million EVs on it by June 2023, across five brands and eight factories. The platform decides cost; the body decides the brand.", "sources": [{"url": "https://newsio.com/2023/06/16/volkswagen-group-hits-1-million-mark-in-meb-based-ev-production-milestone/?amp=1", "label": "Newsio, VW Group hits 1 million MEB EVs"}]}, "evidence": {"kind": "faceOff", "prompt": "Which choice suits a plan for many EVs over years?", "left": {"name": "Convert the gas platform", "note": "Faster, but compromises the battery"}, "right": {"name": "Build a dedicated platform", "note": "Slower start, shared by many models"}, "correctIndex": 1, "explanation": "For many EVs over years, a battery-first platform shared across models pays back, as MEB did."}, "numbers": {"kind": "numberSense", "prompt": "MEB was unveiled in 2018 and hit 1 million cars in June 2023. About how many years did that take?", "min": 0, "max": 12, "value": 5, "unit": "years", "explanation": "About five years. A dedicated platform pays back over many years and many cars."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks whether to convert the gas platform for three planned EVs.", "prompt": "What do you recommend?", "options": ["Build each EV on a new platform", "A dedicated platform for the long run", "Convert it and never revisit"], "correctIndex": 1, "consequences": ["Separate platforms multiply cost.", "Three EVs and more later justify a shared base.", "Compromises stay in every car built on it."], "explanation": "With several EVs planned, a dedicated platform avoids compromises and spreads cost."}, "proReasoning": "Strong advisers match the platform choice to how many cars will use it over time.", "commonMistake": "Choosing the fastest option for a long-term program.", "mentalModel": "Match the platform to the volume ahead."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker announces its EVs will stay on converted gas platforms for years.", "prompt": "What concern should you raise?", "options": ["Far too much battery space", "Platforms that are too new", "Higher costs and compromises"], "correctIndex": 2, "consequences": ["Converted platforms usually have less space.", "Converted platforms are older, not newer.", "Converted bases compromise on battery layout."], "explanation": "Dedicated platforms avoid compromises and spread cost. Converted ones can lag on both."}, "proReasoning": "Investors treat platform strategy as a signal of long-term EV cost competitiveness.", "commonMistake": "Ignoring the base under the cars.", "mentalModel": "Platform strategy signals long-term cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup has no gas platform. You are designing your first EV.", "prompt": "What is your advantage?", "options": ["You can design battery-first", "You must convert a gas platform", "You need no platform at all"], "correctIndex": 0, "consequences": ["No legacy base means no compromises.", "You have no gas platform to convert.", "Every car needs a base."], "explanation": "Without a legacy platform, a startup can build battery-first and share it across future models."}, "proReasoning": "Founders turn having no legacy into an edge by designing the right base from the start.", "commonMistake": "Copying legacy carmakers' compromises.", "mentalModel": "No legacy, no compromise."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some early EVs had less room than newer ones.", "prompt": "What's one reason?", "options": ["Newer EVs have no rear seats", "They sat on platforms made for gas cars", "Early EVs had no batteries at all"], "correctIndex": 1, "consequences": ["Newer EVs still have seats.", "Converted bases left less room for the battery.", "Every EV has a battery."], "explanation": "Converted gas platforms compromised on space. Dedicated platforms are designed around the battery."}, "proReasoning": "A car's shape often follows the platform underneath.", "commonMistake": "Thinking all EVs are designed the same way.", "mentalModel": "The base shapes the car."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8e9dfdce80de$ml$]::text[]),
($ml$a69f526d-e7ec-552f-898a-ee20c8be87dd$ml$::uuid, $ml$ev$ml$, 14, 1, $ml${"id": "ev-d14-c1", "title": "Honda's EV built by GM", "lessonTitle": "Renting a rival's platform", "slot": 1, "type": "apply", "brief": {"headline": "Honda's Prologue EV is built by GM in Mexico on GM's Ultium-based platform, sharing much with the Chevy Blazer EV. Honda sold 33,017 in the US in 2024.", "kicker": "Apply it: what does Honda gain and give up?", "fullText": "The Honda Prologue is built at GM's Ramos Arizpe plant in Mexico on GM's BEV3 platform, based on the Ultium architecture. It is heavily based on the Chevrolet Blazer EV. Honda gave it its own sheetmetal and interior and tuned the steering and suspension.\n\nProduction began in January 2024. US sales reached 33,017 in 2024 and 39,194 in 2025. Honda got an EV to market fast without building its own platform. In return, a rival built the base, and the factory, under the Honda badge.", "sources": [{"url": "https://en.wikipedia.org/wiki/Honda_Prologue", "label": "Wikipedia, Honda Prologue"}]}, "evidence": {"kind": "sortSignal", "prompt": "Who provides each part of the Prologue?", "buckets": ["GM provides", "Honda provides"], "items": [{"text": "The Ultium-based platform", "bucket": 0}, {"text": "The factory in Ramos Arizpe", "bucket": 0}, {"text": "The exterior sheetmetal and interior", "bucket": 1}, {"text": "Steering and suspension tuning", "bucket": 1}], "explanation": "GM provides the base and the factory. Honda gives the car its look and feel."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand Prologues did Honda sell in the US in 2025?", "min": 0, "max": 100, "value": 39, "unit": "K", "explanation": "39,194 in 2025, up from 33,017 in 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Honda. They ask why the Prologue is built by GM.", "prompt": "Which answer shows the trade-off?", "options": ["Speed to market, at the cost of control", "GM makes better cars than Honda", "Honda stopped building its own cars"], "correctIndex": 0, "consequences": ["You name both the gain and the price.", "This is a strategy choice, not a quality verdict.", "Honda builds many cars itself."], "explanation": "Using GM's platform got Honda an EV fast, but a rival controls its base and factory."}, "proReasoning": "Strong candidates name what a partnership buys and what it costs.", "commonMistake": "Treating partnerships as a sign of weakness or strength only.", "mentalModel": "Name the gain and the price."}, "invest": {"call": {"kind": "theCall", "situation": "Honda relies on GM to build its main US EV.", "prompt": "What risk should you watch?", "options": ["The Prologue having no battery", "GM's plans and plant decisions", "Honda running out of badges"], "correctIndex": 1, "consequences": ["It runs on an Ultium-based battery.", "A rival's factory and platform carry Honda's EV.", "Badges are not the constraint."], "explanation": "GM builds the car on its platform. Changes in GM's plans can affect Honda's EV supply."}, "proReasoning": "Investors track a partner's decisions when a key product depends on it.", "commonMistake": "Ignoring dependency on a rival.", "mentalModel": "Track the partner you depend on."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your EV startup has a design but no platform. A big carmaker offers its base.", "prompt": "What do you weigh most?", "options": ["Whether their logo is nice", "Whether you need a battery", "Speed now versus control later"], "correctIndex": 2, "consequences": ["Logos do not decide the deal.", "Every EV needs a battery.", "That is the real trade, as Honda found."], "explanation": "A partner platform gets you to market fast but limits your control over the base."}, "proReasoning": "Founders weigh speed against control, and plan how to regain control later.", "commonMistake": "Taking a partner platform without a plan for later.", "mentalModel": "Weigh speed now against control later."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised that a Honda shares parts with a Chevrolet.", "prompt": "What's going on?", "options": ["Honda uses GM's EV platform", "Honda owns GM", "They are the same car"], "correctIndex": 0, "consequences": ["GM builds the Prologue on its platform.", "They are separate companies.", "Honda gave it its own body and tuning."], "explanation": "The Prologue is built by GM on its Ultium-based platform, with Honda's own design."}, "proReasoning": "Rivals often share platforms. The badge does not tell you who built the base.", "commonMistake": "Assuming rivals never cooperate.", "mentalModel": "Rivals can share a base."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5ddaaaf3248f$ml$]::text[]),
($ml$ac917378-9191-5fcc-b120-c2c7c2927e94$ml$::uuid, $ml$ev$ml$, 14, 2, $ml${"id": "ev-d14-c2", "title": "Borrowing scale", "lessonTitle": "Renting a rival's platform", "slot": 2, "type": "connect", "brief": {"headline": "Ford agreed to build 1.2 million EVs on Volkswagen's MEB platform. Four US EV startups that tried to build their own scale went bankrupt.", "kicker": "Connect day 6 and day 14: rent the scale or build it.", "fullText": "On day 6 you saw Lordstown, Fisker, Canoo and Nikola go bankrupt between 2023 and 2025, after spending years building scale before enough cars sold. On day 14 you saw Ford take another route: it agreed to build 1.2 million EVs on Volkswagen's MEB platform over six years.\n\nUsing a rival's platform let Ford electrify quickly and cost-effectively instead of developing everything itself. Making cars at scale is harder than designing them. Renting scale is one way around that wall.", "sources": [{"url": "https://electriccarsreport.com/2025/02/nikola-files-for-chapter-11-bankruptcy-joining-growing-list-of-fallen-ev-startups/", "label": "Electric Cars Report, Nikola joins fallen EV startups"}, {"url": "https://www.carz.com.my/2022/05/volkswagen-and-ford-building-the-future-12-million-units-of-meb-electric-vehicles", "label": "Carz, VW and Ford to build 1.2 million MEB EVs"}]}, "evidence": {"kind": "faceOff", "prompt": "Which path needed less upfront cash?", "left": {"name": "Ford using MEB", "note": "Built on a rival's finished platform"}, "right": {"name": "Startups building alone", "note": "Own platforms and factories first"}, "correctIndex": 0, "explanation": "Ford used a platform Volkswagen had already paid to develop. The startups funded everything themselves."}, "numbers": {"kind": "numberSense", "prompt": "Over how many years did Ford plan its 1.2 million MEB-based EVs?", "min": 0, "max": 15, "value": 6, "unit": "years", "explanation": "Six years. The deal doubled from 600,000 to 1.2 million units."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what EV startups could learn from Ford's MEB deal.", "prompt": "Which answer is sharpest?", "options": ["Avoid partners at all costs", "Borrow scale before building it", "Build every factory yourself"], "correctIndex": 1, "consequences": ["Partners can save years and billions.", "Ford moved fast using a finished platform.", "That is what drained the failed startups."], "explanation": "Ford used Volkswagen's platform. Startups that built everything first ran out of cash."}, "proReasoning": "Strong candidates connect strategy across companies to draw a lesson.", "commonMistake": "Treating big carmakers and startups as having nothing in common.", "mentalModel": "Borrow scale before you build it."}, "invest": {"call": {"kind": "theCall", "situation": "An EV startup plans its own platform and plant. Another plans to use a partner's platform.", "prompt": "Which has the lower cash risk?", "options": ["The one building everything itself", "Both carry equal cash risk", "The one using a partner's platform"], "correctIndex": 2, "consequences": ["That was the pattern behind four bankruptcies.", "Upfront spending differs greatly.", "It avoids paying to develop a platform."], "explanation": "Using a finished platform cuts the cash needed before sales, the gap that sank the failed startups."}, "proReasoning": "Investors favor plans that turn big upfront costs into shared or per-car costs.", "commonMistake": "Rewarding ambition without checking the cash it needs.", "mentalModel": "Less upfront cash, less risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan your startup's EV. A big carmaker offers its platform, like Volkswagen did for Ford.", "prompt": "What is the main reason to accept?", "options": ["It saves years of development cash", "It guarantees your car will sell", "It removes all your costs"], "correctIndex": 0, "consequences": ["You avoid the spending that sank others.", "Sales still depend on the product.", "You still pay for the platform and parts."], "explanation": "A finished platform lets you skip the costliest part of building a car company."}, "proReasoning": "Founders borrow the hardest part of the business and compete on what they do best.", "commonMistake": "Insisting on building every layer yourself.", "mentalModel": "Borrow the hardest part."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how Ford launched EVs fast while startups struggled.", "prompt": "Which fact explains part of it?", "options": ["EV startups were banned outright", "Ford used Volkswagen's EV platform", "Ford had no costs at all"], "correctIndex": 1, "consequences": ["Startups were free to build cars.", "It built on a platform already developed.", "Ford still paid for the platform and parts."], "explanation": "Ford used Volkswagen's MEB platform instead of developing everything itself."}, "proReasoning": "Speed often comes from reusing work someone else already did.", "commonMistake": "Thinking speed comes only from working harder.", "mentalModel": "Reuse beats rebuilding."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2b084ab6992c$ml$]::text[]),
($ml$78ee0fe0-94fa-5226-8fab-af298b01d2c5$ml$::uuid, $ml$ev$ml$, 14, 3, $ml${"id": "ev-d14-c3", "title": "Renting a rival's base", "lessonTitle": "Renting a rival's platform", "slot": 3, "type": "decide", "brief": {"headline": "Ford's MEB deal doubled from 600,000 to 1.2 million EVs over six years. Ford moved faster but depends on Volkswagen's platform.", "kicker": "Decide: rent a rival's platform or build your own?", "fullText": "You lead strategy at a mid-sized carmaker that must launch EVs in Europe within three years. Ford faced the same choice and agreed to build EVs on Volkswagen's MEB platform. The plan started at 600,000 units and doubled to 1.2 million over six years, with the first model built at Ford's Cologne plant from 2023.\n\nFord saved development time and money, and Volkswagen spread its platform cost over more cars. But sharing a base also means sharing its limits.", "sources": [{"url": "https://www.carz.com.my/2022/05/volkswagen-and-ford-building-the-future-12-million-units-of-meb-electric-vehicles", "label": "Carz, VW and Ford to build 1.2 million MEB EVs"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each point about renting a platform.", "buckets": ["Benefit", "Cost"], "items": [{"text": "Launch faster than developing alone", "bucket": 0}, {"text": "Spend less on development", "bucket": 0}, {"text": "Depend on a rival's roadmap", "bucket": 1}, {"text": "Share the platform's limits", "bucket": 1}], "explanation": "Renting a platform buys speed and savings. It costs control."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand units did the Ford MEB plan start at, before doubling?", "min": 0, "max": 1500, "value": 600, "unit": "K", "explanation": "600,000, later doubled to 1.2 million over six years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO must launch EVs in three years and has no EV platform.", "prompt": "What do you recommend?", "options": ["Build your own and miss the date", "Delay all EV plans indefinitely", "Rent now, build skills alongside"], "correctIndex": 2, "consequences": ["Developing alone may take longer than three years.", "Delay cedes the market to rivals.", "You hit the date and keep learning."], "explanation": "Renting gets you to market on time, like Ford. Building skills alongside keeps options open."}, "proReasoning": "Strong advisers combine a short-term rental with a long-term plan to regain control.", "commonMistake": "Choosing pride over the deadline.", "mentalModel": "Rent to hit the date, learn to own later."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker rents a rival's platform for all its EVs, with no plan of its own.", "prompt": "What long-term risk do you see?", "options": ["Lasting dependence on a rival", "Too much control over its cars", "Platforms that cost nothing"], "correctIndex": 0, "consequences": ["The rival sets the base for every EV it sells.", "Renting gives less control, not more.", "It pays for the platform it rents."], "explanation": "Renting trades control for speed. Without its own plan, a carmaker stays dependent."}, "proReasoning": "Investors check whether a renter has a path to its own capabilities.", "commonMistake": "Treating a rental as a permanent strategy without cost.", "mentalModel": "Check the path off the rental."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a platform company and want to license your EV base to carmakers.", "prompt": "What is your strongest pitch?", "options": ["No need for any battery packs", "A faster, cheaper launch", "Total control for the renter"], "correctIndex": 1, "consequences": ["EVs still need batteries.", "That is exactly what Ford got from MEB.", "Renters accept less control."], "explanation": "Ford rented MEB to move fast and save money. That is the value a platform licensor sells."}, "proReasoning": "Founders selling a platform pitch speed and savings, and are honest about shared limits.", "commonMistake": "Promising renters full control.", "mentalModel": "Sell speed and savings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Volkswagen would help a rival like Ford.", "prompt": "What's in it for Volkswagen?", "options": ["Volkswagen secretly owns Ford", "Ford paid in gas cars instead", "More cars on MEB cut its cost"], "correctIndex": 2, "consequences": ["They are separate companies.", "The deal was about EV platforms.", "Spreading the platform cost helps Volkswagen too."], "explanation": "More cars on MEB spread its development cost, so both sides gained."}, "proReasoning": "Rivals cooperate when both sides gain. Shared platforms are a common example.", "commonMistake": "Assuming rivals never help each other.", "mentalModel": "Rivals cooperate when both gain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c1de78bbd23d$ml$]::text[]),
($ml$a6784689-36c8-5e88-ac8a-805d7bb2198c$ml$::uuid, $ml$ev$ml$, 15, 1, $ml${"id": "ev-d15-c1", "title": "Volkswagen buys into Xpeng", "lessonTitle": "Who controls the car's brain", "slot": 1, "type": "apply", "brief": {"headline": "In July 2023, Volkswagen agreed to invest about $700 million in Xpeng for a 4.99% stake. Two VW EVs for China would use Xpeng's platform and driver-assist software.", "kicker": "Apply it: why would a giant buy a young rival's tech?", "fullText": "On July 26, 2023, Volkswagen agreed to invest about $700 million in Chinese EV maker Xpeng, paying $15 per US-traded share for a 4.99% stake and a board seat. Xpeng's shares closed up over 26%.\n\nThe two companies would develop two midsize VW-brand EVs for China, based on the platform behind Xpeng's G9 SUV and including Xpeng's driver-assist software, due in 2026. VW's China chief cited faster time to market and lower development costs. A global giant chose to buy tech from a young local rival.", "sources": [{"url": "https://www.cnbc.com/amp/2023/07/26/volkswagen-xpeng-to-develop-two-new-evs-for-china.html", "label": "CNBC, Volkswagen buys stake in Xpeng"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Volkswagen get from Xpeng for its China EVs?", "options": ["Full ownership of Xpeng itself", "A platform and driver-assist software", "A cheaper paint supplier in China"], "correctIndex": 1, "explanation": "The VW EVs would use the platform behind the G9 and Xpeng's driver-assist software. VW took a 4.99% stake, not control."}, "numbers": {"kind": "numberSense", "prompt": "What stake in Xpeng did Volkswagen take, in percent?", "min": 0, "max": 30, "value": 5, "unit": "%", "explanation": "4.99%, for about $700 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Volkswagen China. They ask what the Xpeng deal says about the industry.", "prompt": "Which answer shows insight?", "options": ["Volkswagen is leaving China", "Software and speed now drive carmaking", "Xpeng is now owned by Volkswagen"], "correctIndex": 1, "consequences": ["The deal is about building more for China.", "A giant paid for a young rival's software.", "VW took 4.99%, not ownership."], "explanation": "VW paid for Xpeng's platform and driver-assist software to move faster in China."}, "proReasoning": "Strong candidates read deals as signals of where value in the industry is moving.", "commonMistake": "Reading a minority stake as a takeover.", "mentalModel": "Read deals as signals of value."}, "invest": {"call": {"kind": "theCall", "situation": "Xpeng's shares jumped over 26% after the VW deal.", "prompt": "What did the market likely reward?", "options": ["Xpeng becoming a VW brand", "An end to Xpeng's own car sales", "Proof its tech is worth paying for"], "correctIndex": 2, "consequences": ["Xpeng stays independent with VW as a holder.", "Xpeng keeps selling its own cars.", "A global giant validated its software."], "explanation": "A major carmaker paying for Xpeng's tech showed it could earn beyond its own cars."}, "proReasoning": "Investors value when a company's technology finds buyers beyond its own products.", "commonMistake": "Missing the signal in who pays for a company's tech.", "mentalModel": "Outside buyers validate the tech."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds driver-assist software for your own EVs.", "prompt": "What does the VW-Xpeng deal suggest?", "options": ["Carmakers may license your software", "Software has no value on its own", "Only hardware sells to carmakers"], "correctIndex": 0, "consequences": ["VW paid for Xpeng's software in its own cars.", "VW paid hundreds of millions for it.", "Here, software was part of the deal."], "explanation": "VW paid to put Xpeng's driver-assist software in its own cars. Software can be a product."}, "proReasoning": "Founders consider whether their software could earn as a product sold to others.", "commonMistake": "Treating software only as a feature of your own car.", "mentalModel": "Your software may be a product."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised a giant like Volkswagen paid a young Chinese startup.", "prompt": "What's the reason?", "options": ["To shut Xpeng down for good", "To get its tech faster", "Because Xpeng makes gas engines"], "correctIndex": 1, "consequences": ["Xpeng keeps operating independently.", "VW cited faster time to market and lower costs.", "Xpeng builds EVs and software."], "explanation": "VW wanted to bring EVs to China faster and cheaper using Xpeng's technology."}, "proReasoning": "Big companies buy speed when building it themselves would take too long.", "commonMistake": "Assuming giants always build everything themselves.", "mentalModel": "Giants sometimes buy speed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:49efbf9a601b$ml$]::text[]),
($ml$0ad1d439-7c8f-5066-8a89-a4b97526d8f2$ml$::uuid, $ml$ev$ml$, 15, 2, $ml${"id": "ev-d15-c2", "title": "The platform and the brain", "lessonTitle": "Who controls the car's brain", "slot": 2, "type": "connect", "brief": {"headline": "Volkswagen built 1 million EVs on its MEB platform by June 2023. In November 2024, it invested $5.8 billion in Rivian for software and electrical architecture.", "kicker": "Connect day 13 and day 15: owning the base is not owning the brain.", "fullText": "On day 13 you saw Volkswagen's MEB platform carry 1 million EVs across five brands by June 2023. On day 15 you saw Volkswagen launch a 50:50 joint venture with Rivian in November 2024, investing $5.8 billion, more than the $5 billion it first planned.\n\nThe venture works on electrical architecture and software for software-defined vehicles, building on Rivian's design for its R2. Volkswagen had mastered the shared physical base. The car's brain, the software that controls it after the sale, was another matter.", "sources": [{"url": "https://newsio.com/2023/06/16/volkswagen-group-hits-1-million-mark-in-meb-based-ev-production-milestone/?amp=1", "label": "Newsio, VW Group hits 1 million MEB EVs"}, {"url": "https://www.electrive.com/2024/11/13/volkswagen-and-rivian-officially-launch-their-joint-venture", "label": "electrive, VW and Rivian launch their joint venture"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["MEB carried 1 million EVs by June 2023.", "The Rivian venture is a 50:50 company.", "Volkswagen paid Rivian for battery cells."], "fakeIndex": 2, "explanation": "The venture is about electrical architecture and software, not battery cells."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did Volkswagen invest in Rivian?", "min": 0, "max": 15, "value": 5.8, "unit": "B", "explanation": "$5.8 billion, up from an initial plan of up to $5 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why Volkswagen needed Rivian if it already had MEB.", "prompt": "Which answer is sharpest?", "options": ["MEB had stopped working entirely", "Rivian builds VW's batteries", "MEB is the base; Rivian, software"], "correctIndex": 2, "consequences": ["MEB carried 1 million cars.", "The venture is about software and electronics.", "You separate hardware platforms from software."], "explanation": "A physical platform and the software brain are different layers. VW bought help with the second."}, "proReasoning": "Strong candidates separate a car's physical platform from its software architecture.", "commonMistake": "Assuming one platform covers everything a car needs.", "mentalModel": "Base and brain are different layers."}, "invest": {"call": {"kind": "theCall", "situation": "You compare carmakers. One owns a strong EV platform but buys its software from a partner.", "prompt": "What should you weigh?", "options": ["Who controls updates later", "How many seats each car has", "The color of each brand logo"], "correctIndex": 0, "consequences": ["Software owners shape the car after purchase.", "Seats say little about software control.", "Logos are irrelevant here."], "explanation": "Whoever owns the software owns the upgrades and the customer relationship after the sale."}, "proReasoning": "Investors ask who owns the software layer, since it drives value after the car is sold.", "commonMistake": "Valuing carmakers only on hardware.", "mentalModel": "Ask who owns the software layer."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your EV startup has strong electrical architecture but weak sales.", "prompt": "What could you learn from Rivian?", "options": ["Stop working on software", "Your architecture may be worth licensing", "Hide your architecture from partners"], "correctIndex": 1, "consequences": ["Software is where the value is moving.", "VW paid $5.8 billion for Rivian's architecture work.", "Hiding it removes a revenue path."], "explanation": "Rivian turned its architecture into a $5.8 billion venture. Strong software can be a business."}, "proReasoning": "Founders look for value in their technology beyond their own product sales.", "commonMistake": "Overlooking the worth of what you built along the way.", "mentalModel": "Your tech can be a business."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a huge carmaker would pay a small one billions.", "prompt": "What did Volkswagen want?", "options": ["Rivian's factories in Illinois", "Rivian's gas engine designs", "Rivian's software design"], "correctIndex": 2, "consequences": ["The deal centers on software.", "Rivian makes only EVs.", "The venture builds on Rivian's R2 architecture."], "explanation": "VW wanted Rivian's electrical architecture and software for software-defined vehicles."}, "proReasoning": "In modern cars, software can be worth more than size.", "commonMistake": "Thinking the bigger company always has the better tech.", "mentalModel": "Size is not software."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0ef6d51a906d$ml$]::text[]),
($ml$5f2f02fe-6306-5d11-aa13-dad3657d877a$ml$::uuid, $ml$ev$ml$, 15, 3, $ml${"id": "ev-d15-c3", "title": "Build the brain or buy it", "lessonTitle": "Who controls the car's brain", "slot": 3, "type": "decide", "brief": {"headline": "Volkswagen invested $5.8 billion in a 50:50 venture with Rivian for software-defined vehicles. The first cars using it are expected in 2027.", "kicker": "Decide: build your own car software or partner for it?", "fullText": "You lead technology at a large carmaker whose in-house software is behind rivals. In November 2024, Volkswagen faced a similar gap and launched a 50:50 joint venture with Rivian, investing $5.8 billion. The venture works on electrical architecture and software, building on Rivian's design for its R2.\n\nIn a software-defined vehicle, software controls more and more of the car, and whoever owns it owns the upgrades. The first vehicles using the shared technology are expected in 2027. Building alone may take longer; partnering means sharing control.", "sources": [{"url": "https://www.electrive.com/2024/11/13/volkswagen-and-rivian-officially-launch-their-joint-venture", "label": "electrive, VW and Rivian launch their joint venture"}]}, "evidence": {"kind": "buildChain", "prompt": "Order the logic behind the Volkswagen-Rivian deal.", "steps": ["Software controls more of the car", "Volkswagen's own software falls behind", "Rivian has a working architecture for its R2", "They form a 50:50 venture", "Shared tech reaches cars from 2027"], "explanation": "As software grew in importance, VW chose to partner with a company that already had it."}, "numbers": {"kind": "numberSense", "prompt": "The venture launched in late 2024. About how many years until the first cars using it?", "min": 0, "max": 10, "value": 3, "unit": "years", "explanation": "About three: the first vehicles are expected in 2027."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks whether to partner for software like Volkswagen did.", "prompt": "What do you recommend?", "options": ["Partner, with shared control spelled out", "Build alone and accept the delay", "Skip software and sell only hardware"], "correctIndex": 0, "consequences": ["You close the gap and keep influence.", "Rivals keep pulling ahead meanwhile.", "Software owns the customer after the sale."], "explanation": "A partnership closes the gap faster. Clear terms on control protect your future."}, "proReasoning": "Strong advisers pair a partnership with clear terms on who controls what.", "commonMistake": "Partnering without deciding who owns the software.", "mentalModel": "Partner fast, define control clearly."}, "invest": {"call": {"kind": "theCall", "situation": "A carmaker announces a software joint venture with a younger rival.", "prompt": "What should you look for in the terms?", "options": ["The venture's office address", "Who owns and controls the software", "How many press photos were taken"], "correctIndex": 1, "consequences": ["Location is not the value.", "Ownership decides who earns from upgrades.", "Photos tell you nothing."], "explanation": "In software-defined cars, control of the software decides who owns the customer after sale."}, "proReasoning": "Investors read software deals for ownership and control, not headline amounts alone.", "commonMistake": "Reacting to the dollar figure without the control terms.", "mentalModel": "Read for control, not just dollars."}, "build_startup": {"call": {"kind": "theCall", "situation": "A giant carmaker wants a 50:50 venture on your startup's software.", "prompt": "What do you protect?", "options": ["Nothing at all; take the money", "The right to stop all updates", "Your right to use it yourself"], "correctIndex": 2, "consequences": ["You could lose your own core tech.", "Blocking updates hurts both sides.", "You keep building your products on it."], "explanation": "Rivian's venture builds on its own R2 design. Keep the right to keep using what you made."}, "proReasoning": "Founders entering ventures keep the rights they need for their own products.", "commonMistake": "Trading away core rights for a big check.", "mentalModel": "Keep the rights you need to build."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why car software matters so much now.", "prompt": "What's the reason?", "options": ["It controls more of the car over time", "Cars no longer need hardware", "Software never changes after sale"], "correctIndex": 0, "consequences": ["Software-defined cars change through updates.", "Cars still need physical parts.", "Updates can change cars after sale."], "explanation": "In software-defined vehicles, software controls more and more of the car, even after it is sold."}, "proReasoning": "A car you buy today can change through software tomorrow.", "commonMistake": "Thinking a car is finished when it leaves the factory.", "mentalModel": "Software keeps changing the car."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3582937b8eec$ml$]::text[])
